const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cfg=window.WELLNESS_CONFIG,sb=window.supabase.createClient(cfg.url,cfg.key,{auth:{storageKey:'wellness-restaurant-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}}),vault=new Vault();
let focusedMissionID='',state=null,page='home',eventID='',missionID='',station='registration',search='',busy=false,contextSyncPending=false,installPrompt=null,authMode='login',recovery=false,syncError='',impactFilter={scope:'approved',mission:'',from:'',to:'',location:''};
const labels={home:'Home',daily:'Daily report',impact:'Reports',guide:'Volunteer guide',stations:'Guest form',guests:'Guests',events:'Events',appointments:'Appointments',programs:'Programs & recipes',reports:'Reports',inventory:'Inventory',team:'Volunteers',audit:'Edit history',settings:'Settings',sync:'Sync center',more:'More'};
const admin=()=>state?.user?.role==='admin',ev=()=>state?.events.find(e=>e.id===eventID),snap=()=>state?.snapshots[eventID]||{records:[],resources:[],audit:[],conflicts:[]};
const records=()=>mergeRecords(snap().records,visibleQueue().filter(o=>o.event_id===eventID));
const assigned=()=>Object.keys(STATIONS);
const allowed=()=>admin()?Object.keys(labels):['home','guide','events','stations','guests','reports','daily','inventory','sync','appointments','programs','team','more'];
