const button=(action,label,id='',kind='primary')=>`<button type="button" class="${kind}" data-action="${action}" data-id="${esc(id)}">${esc(label)}</button>`;
const field=(name,label,value='',type='text',attrs='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const area=(name,label,value='')=>`<label class="full">${esc(label)}<textarea name="${name}" rows="3" maxlength="4000">${esc(value)}</textarea></label>`;
const select=(name,label,options,value='')=>`<label>${esc(label)}<select name="${name}" aria-label="${esc(label)}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`}).join('')}</select></label>`;
