const message=(text)=>{$('#authStatus').textContent=text;};
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),6500);}
async function api(action,data={},publicCall=false){
 const session=(await sb.auth.getSession()).data.session;
 const response=await fetch(cfg.url+'/functions/v1/wellness-api',{method:'POST',headers:{'Content-Type':'application/json',apikey:cfg.key,...(!publicCall&&session?{Authorization:'Bearer '+session.access_token}:{})},body:JSON.stringify({action,...data}),signal:AbortSignal.timeout(action==='create-users'?120000:25000)});
 const json=await response.json();if(!response.ok)throw Object.assign(Error(json.error||'Connection failed.'),{status:response.status});return json;
}
function authView(mode='login'){
 authMode=mode;$('#loginGate').hidden=false;$('#app').hidden=true;
 if(mode==='unlockprevious'){$('#loginForm').innerHTML='<h1>Recover this phone’s saved entries</h1><p>No saved entries will be removed.</p>'+field('previous','Previous offline password','','password','required autocomplete="off"')+field('password','Current online password','','password','required autocomplete="current-password"')+'<p id="authStatus" role="status"></p><button type="submit" class="primary">Unlock and update this phone</button>'+button('login','Return to sign in','','text-button');$('#loginForm').onsubmit=authSubmit;return;}
 const signup=mode==='signup',password=mode==='password';
 $('#loginForm').innerHTML=`<img src="assets/logo.png" alt="Oon Jai" width="52" height="52"><h1>${signup?'Create a volunteer account':password?'Set a new password':'Oon Jai Wellness'}</h1><p>${signup?'Enter a shared mission code after signing up to open its day-and-location sessions.':password?'Choose a new password for your Wellness account.':'Sign in with your assigned email. Existing Restaurant accounts use their current password.'}</p>${signup?field('name','Full name','','text','required maxlength="120" autocomplete="name"'):''}${!password?field('email','Email address',localStorage.getItem('wellness-last-email')||'','email','required autocomplete="username"'):''}${mode!=='forgot'?field('password',password?'New password':'Password','','password',`required autocomplete="${signup||password?'new-password':'current-password'}"`):''}${signup||password?field('confirm','Confirm password','','password','required autocomplete="new-password"')+`<small>7–128 characters, including at least one letter and one number.</small>`:''}<div id="authStatus" role="status" aria-live="polite"></div><button class="primary" type="submit">${signup?'Create account':password?'Save password':mode==='forgot'?'Send recovery email':'Sign in'}</button>${mode==='login'?button('offline','Unlock saved phone offline','','secondary')+button('signup','Create an account','','text-button')+button('forgot','Forgot password?','','text-button')+button('resend','Resend verification','','text-button'):button('login','Return to sign in','','text-button')}`;
 $('#loginForm').onsubmit=authSubmit;
}
async function authSubmit(e){e.preventDefault();const form=e.target,b=form.querySelector('[type=submit]');b.disabled=true;const data=Object.fromEntries(new FormData(form));message('Please wait…');
 try{
  if(authMode==='unlockprevious'){const email=form.dataset.email;state=await vault.open(email,data.previous,false);const result=await sb.auth.signInWithPassword({email,password:data.password});if(result.error)throw result.error;if(state.user&&state.user.id!==result.data.user.id)throw Error('Account identity mismatch.');await vault.rekey(data.password);await refreshAccess();if(state.user.temporary_password){authView('password');return;}openWorkspace();await sync();return;}
  if(authMode==='signup'){if(data.password!==data.confirm)throw Error('Passwords do not match.');if(!strongPassword(data.password))throw Error('Use all the password requirements shown above.');const result=await api('signup',data,true);message(result.message);return;}
  if(authMode==='forgot'){const {error}=await sb.auth.resetPasswordForEmail(data.email,{redirectTo:cfg.recovery});if(error)throw error;message('Recovery requested. If the account exists, check your email. Use the newest email link to set your password here in Wellness.');return;}
  if(authMode==='password'){if(data.password!==data.confirm||!strongPassword(data.password))throw Error('Match both passwords and meet all requirements.');await api('password',{password:data.password});if(vault.key)await vault.rekey(data.password);vault.close();state=null;recovery=false;authView('login');message('Password updated. Sign in with your new password.');return;}
  const email=String(data.email).trim().toLowerCase();const {data:auth,error}=await sb.auth.signInWithPassword({email,password:data.password});if(error)throw error;
  try{state=await vault.open(email,data.password,true);}catch(error){if(error.code==='VAULT_PASSWORD'){authView('unlockprevious');$('#loginForm').dataset.email=email;message('Your online password works. Enter this phone’s previous password to recover its saved entries, then enter the current online password.');return;}throw error;}
  if(state.user&&state.user.id!==auth.user.id)throw Error('Offline account identity mismatch.');
  localStorage.setItem('wellness-last-email',email);
  await refreshAccess();if(state.user.temporary_password){authView('password');return;}
  openWorkspace();await sync();
 }catch(err){message(err.message||'Unable to sign in.');}finally{b.disabled=false;}
}
async function refreshAccess(){const b=await api('bootstrap');await vault.edit(s=>{s.user=b.member;s.events=[...b.events,...(s.regularQueue||[]).filter(e=>!b.events.some(x=>x.id===e.id)&&canSeeEvent(b.member,b.memberships||[],e))];s.directory=b.directory||[];s.tickets=b.tickets||[];s.inventory=b.inventory||{locations:[],balances:[],issues:[],moves:[],legacy:[]};s.assignments=b.assignments;s.members=b.members;s.roster=b.roster||[];s.teamMemberships=b.teamMemberships||[];s.attendance=b.attendance||[];s.missions=b.missions||[];s.memberships=b.memberships||[];s.grades=(b.grades||[]).sort((a,b)=>Number(a.grade)-Number(b.grade));s.alerts=b.alerts||[];s.totals=b.totals;s.dailyMetrics=b.dailyMetrics||[];s.missionCounts=b.missionCounts||{};s.preparedUntil=Date.now()+7*86400000;const ids=new Set(s.events.map(e=>e.id));for(const key of Object.keys(s.profileHistories||{}))s.profileHistories[key]=s.profileHistories[key].filter(r=>canSeeRecord(s.user,s.memberships,s.events,r));for(const id of Object.keys(s.snapshots)){if(!ids.has(id)){delete s.snapshots[id];continue;}const snapshot=s.snapshots[id];snapshot.records=snapshot.records.filter(r=>canSeeRecord(s.user,s.memberships,s.events,r));if(s.user.role!=='admin'){snapshot.audit=[];snapshot.conflicts=[];snapshot.devices=[];const event=s.events.find(e=>e.id===id),since=accessSince(s.user,s.memberships.find(mm=>mm.mission_id===event.mission_id));snapshot.resources=snapshot.resources.filter(r=>Date.parse(r.created_at)>=since);}}});state=vault.state;if(focusedMissionID&&!state.missions.some(m=>m.id===focusedMissionID))focusedMissionID='';alignContext();}
function openWorkspace(){if(!state?.user)return;focusedMissionID=state.missions.some(m=>m.id===state.navigation?.workspaceID&&m.kind!=='regular')?state.navigation.workspaceID:'';$('#loginGate').hidden=true;$('#app').hidden=false;page=allowed().includes(location.hash.slice(1))?location.hash.slice(1):'home';render();}
async function offline(){try{const d=Object.fromEntries(new FormData($('#loginForm')));state=await vault.open(String(d.email).trim(),d.password,false);if(!state.user)throw Error('Prepare the phone online first.');if(state.user.temporary_password)throw Error('Change your temporary password online first.');if(state.user.status==='disabled'||state.preparedUntil<Date.now())throw Error('Reconnect to refresh this phone’s access. Saved entries remain safe.');alignContext();openWorkspace();toast('Offline workspace unlocked. Only this phone’s saved data is available.');}catch(e){message(e.message);}}
function canWork(){if(state?.user?.status!=='active'||state.user.temporary_password)throw Error('Sign in and join the mission first.');if(!state.device)throw Error('Use Prepare phone in this workspace while online first.');if(state.preparedUntil<Date.now())throw Error('Reconnect to renew this phone’s mission access. Your saved entries remain safe.');if(!ev()||ev().closed)throw Error('Choose an open event.');}
async function prepare(){await refreshAccess();if(!state.user.initials)throw Error('Your initials could not be reserved. Retry preparation online.');const d=await api('device',{id:state.deviceId,label:navigator.userAgent.includes('Mobile')?'Volunteer phone':'Computer / tablet'});await vault.edit(s=>{s.device=d;});state=vault.state;await navigator.storage?.persist?.();await refreshTickets();await sync();if(syncError)throw Error(syncError);toast('Phone prepared. Guest numbers and event data are ready.');}
async function sync(){if(busy||!state||!vault.key||!navigator.onLine)return;busy=true;syncError='';updateStatus();try{
 await navigator.locks.request('wellness-sync-'+vault.email,async()=>{
  if(!state||!vault.key)return;
  await refreshAccess();if(state.user.temporary_password){authView('password');return;}if(state.user.status!=='active')return;
  await vault.reload();state=vault.state;await refreshTickets();
  for(const localDay of [...(state.regularQueue||[])]){const saved=await api('regular-day',{event:localDay});await vault.edit(s=>{s.regularQueue=(s.regularQueue||[]).filter(e=>e.id!==localDay.id);s.events=s.events.filter(e=>e.id!==localDay.id&&e.id!==saved.id);s.events.push(saved);if(localDay.id!==saved.id){for(const q of s.queue)if(q.event_id===localDay.id)q.event_id=saved.id;if(s.snapshots[localDay.id]){s.snapshots[saved.id]=s.snapshots[localDay.id];for(const r of s.snapshots[saved.id].records)r.event_id=saved.id;delete s.snapshots[localDay.id];}if(s.navigation?.eventID===localDay.id)s.navigation.eventID=saved.id;}});if(eventID===localDay.id)eventID=saved.id;state=vault.state;}
  const hadUploads=state.queue.some(o=>!['conflict','reviewed'].includes(o.status));
  const touched=[...new Set([...(state.reportedDays||[]),...state.queue.map(o=>o.event_id),eventID].filter(id=>state.events.some(e=>e.id===id)))];
  for(const operation of [...state.queue].filter(o=>!['conflict','reviewed'].includes(o.status))){
   try{const result=await api('submit',{operation});await vault.edit(s=>{const q=s.queue.find(o=>o.id===operation.id);if(!q)return;if(result.status==='saved'){const snapshot=s.snapshots[q.event_id]||={records:[],resources:[],audit:[],conflicts:[]};snapshot.records=mergeRecords(snapshot.records,[{...q,author:s.user.id}]).map(r=>({...r,pending:false}));s.queue=s.queue.filter(o=>o.id!==q.id);}else{q.status=result.status;q.error=result.message;}});}
   catch(e){if(e.status===401||e.status===403)throw e;await vault.edit(s=>{const q=s.queue.find(o=>o.id===operation.id);if(q){q.status='error';q.error=e.message;}});if(!e.status)throw e;}
  }
  if(state.device)for(const report of pendingDays(vault.state.queue,touched).filter(d=>state.events.some(e=>e.id===d.event_id)))await api('device-status',{...report,device_id:state.device.id});
  if(hadUploads)await refreshAccess();
  const snapshotEvent=eventID;
  if(snapshotEvent){const snapshot=await api('snapshot',{event_id:snapshotEvent});await vault.edit(s=>{s.snapshots[snapshotEvent]=snapshot;const reviewed=new Set((snapshot.reviewed||[]).map(r=>r.id));s.queue=s.queue.filter(o=>!reviewed.has(o.id));});}
  await vault.edit(s=>{s.reportedDays=touched;s.lastSync=new Date().toISOString();});state=vault.state;
 });
 }catch(e){syncError=e.message||'Connection unavailable';toast(syncError);if(e.status===403){$('#dialog').close();authView('login');message(e.message);vault.close();state=null;}}
 finally{busy=false;updateStatus();if(state&&!$('#dialog').open&&!document.activeElement?.matches('input,textarea,select'))render();if(contextSyncPending){contextSyncPending=false;queueMicrotask(()=>sync());}}}
function updateStatus(){const t=$('#syncStatus');if(t)t.textContent=busy?'Syncing…':!navigator.onLine?'Offline':syncError?'Connection needs attention':visibleQueue().length?`${visibleQueue().length} to sync / review`:'Connected';}
const dayPages=['home','stations','daily','appointments','programs','audit','sync'];
const navGroups=[['Workspace',['home','events','guests','inventory','reports']],['Current visit',['stations','daily']],['Tools',['appointments','programs','team','audit']],['Help & phone',['guide','sync','settings']]];
const pageHelp={home:'Large events and everyday wellness care, in one place.',events:'Open an event, or manage your regular-visit workspace.',stations:'Register a new guest or enter an existing guest ID.',guests:'Find a guest, continue a visit, or review their history.',reports:'Results by event, regular visit, date and service.',inventory:'Main stock, event allocations and everyday glasses use.',more:'Reports, team tools and help, all in one place.',settings:'Manage your account, phone and notifications.'};
const navPaths={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',events:'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4',stations:'M9 4H5v17h14V4h-4M9 3h6v4H9ZM8 12h8m-8 4h5',guests:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M15 4a4 4 0 0 1 0 8m3 3a4 4 0 0 1 4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',reports:'M4 20h16M7 16V9m5 7V4m5 12v-5',inventory:'M3 8h18v13H3ZM2 3h20v5H2Zm7 9h6',more:'M4 6h16M4 12h16M4 18h16',sync:'M3 11a9 9 0 0 1 15-6l3 3m0-5v5h-5M21 13A9 9 0 0 1 6 19l-3-3m0 5v-5h5',settings:'M12 3v3m0 12v3M3 12h3m12 0h3M6 6l2 2m8 8 2 2M6 18l2-2m8-8 2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',guide:'M4 4h7l1 2 1-2h7v16h-7l-1 1-1-1H4ZM12 6v15'};
const icon=p=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${navPaths[p]||navPaths.reports}"/></svg>`;
const navLink=(p,kind='nav-item',label=labels[p])=>`<a href="#${p}" class="${kind} ${(page===p||(kind.includes('bottom')&&(focused()?{daily:'reports'}:{stations:'guests',daily:'reports',impact:'reports'})[page]===p))?'active':''}" ${page===p?'aria-current="page"':''}>${icon(p)}<span>${esc(label)}</span></a>`;
function alignContext(){const chosen=resolveContext(state,missionID||eventID?{missionID:focusedMissionID||missionID,eventID}:state.navigation,date());missionID=chosen.missionID;eventID=chosen.eventID;}
async function chooseContext(preferred){const chosen=resolveContext(state,preferred,date());await vault.edit(s=>{s.navigation={...chosen,workspaceID:focusedMissionID};});state=vault.state;missionID=chosen.missionID;eventID=chosen.eventID;search='';render();if(busy)contextSyncPending=true;else await sync();}
function dayContext(){if(focused())return eventContext();if(!state.missions?.length||(!dayPages.includes(page)&&!(page==='guests'&&guestMode==='day')))return '';const e=ev(),days=state.events.filter(d=>d.mission_id===missionID).sort((a,b)=>a.starts.localeCompare(b.starts)||a.location.localeCompare(b.location));return `<section class="day-context" aria-label="Selected mission and day"><div class="context-selects">${select('activeMission','1 · Event / workspace',state.missions.map(m=>[m.id,m.name]),missionID)}${select('activeEvent','2 · Day and location',days.length?days.map(d=>[d.id,d.starts+' · '+d.location]):[['','No days scheduled']],eventID)}</div><div class="context-caption"><span>${e?esc(e.starts)+' · '+esc(e.location):'Choose a mission with a scheduled day.'}</span>${e?`<span class="badge ${e.sample?'gold':''}">${e.sample?'Fictional sample':e.approval==='approved'?'Approved · read only':e.closed?'Closed day':e.starts===date()?'Today':'Selected day'}</span>`:''}<a href="#events">View calendar →</a></div>${e?`<nav class="day-tabs" aria-label="Day workspace">${[['stations','Guest form'],['guests','Records'],['daily','Daily report'],['inventory','Glasses stock']].map(([p,l])=>p==='guests'?button('dayrecords',l,'','day-tab'):p==='inventory'?button('daystock',l,'','day-tab'):navLink(p,'day-tab',l)).join('')}</nav>`:''}</section>`;}
function render(){
 if(!state)return;if(!allowed().includes(page)||focused()&&!eventPages.includes(page))page='home';alignContext();
 const isEvent=!!focusedMissionID;document.body.classList.toggle('event-focus',isEvent);const groups=isEvent?eventNavGroups:navGroups;$('#desktopNav').innerHTML=groups.map(([title,pages])=>{const visible=pages.filter(p=>allowed().includes(p));return visible.length?`<div class="nav-group"><p class="nav-label">${title}</p>${visible.map(p=>navLink(p,'nav-item',isEvent?({home:'Event overview',stations:'Registration & stations',guests:'Guests & queue',events:'Days & locations',inventory:'Event stock',reports:'Event reports',sync:'Sync & review'}[p]||labels[p]):labels[p])).join('')}</div>`:'';}).join('');
 const primary=isEvent?['home','stations','guests','reports','sync']:['home','events','guests','inventory','reports'];$('#bottomNav').innerHTML=primary.map(p=>navLink(p,`bottom-link ${p==='more'&&!primary.includes(page)?'active':''}`,(isEvent?{home:'Overview',stations:'Stations',guests:'Guests',reports:'Reports',sync:'Sync'}:{home:'Home',events:'Events',guests:'Guests',inventory:'Inventory',reports:'Reports'})[p])).join('');
 $('#crumb').textContent=labels[page];$('.user-panel').innerHTML=`<span class="avatar">${esc(state.user.initials||'?')}</span><span>${esc(state.user.name)}<small>${admin()?'Administrator':'Volunteer'} · Lock / sign out</small></span>`;$('.desktop-avatar').textContent=state.user.initials||'?';
 const pending=state.user.status==='disabled';
 const top=isEvent?eventHeading():`<div class="page-head"><div><div class="eyebrow">Oon Jai · Wellness</div><h1>${labels[page]}</h1><p class="subtext">${pageHelp[page]||'Your mission workspace.'}</p></div><div class="actions">${page==='home'?'':button('regularvisit','New regular visit','','secondary')}${button('sync','Sync now','','secondary')}<a href="#more" class="secondary" aria-label="Tools and settings">${icon('settings')}</a></div></div>${admin()&&state.alerts?.length?`<div class="admin-alert" role="alert"><strong>${state.alerts.length} conflicting submission${state.alerts.length===1?'':'s'} need review.</strong>${button('alerts','Review alerts','','secondary')}</div>`:''}${page==='home'?'':dayContext()}`;
 const content=dayPages.includes(page)&&page!=='home'&&page!=='sync'&&!ev()?()=>`<section class="panel"><h2>Choose a day to begin</h2><p class="subtext">Open a date and location from your mission calendar.</p><div class="actions spaced">${button('missions','Choose mission & day')}</div></section>`:({home:overview,impact:impactPage,guide:guidePage,stations:stationPage,guests:guestPage,events:eventPage,appointments:appointmentPage,programs:programPage,reports:reportPage,daily:dailyReportPage,inventory:inventoryPage,team:teamPage,audit:auditPage,settings:settingsPage,sync:syncPage,more:morePage}[page]);
 $('#main').innerHTML=top+(pending?note('Your Wellness access is disabled. Contact an administrator. Saved entries remain on this phone.'):content());
 if(pending&&page==='settings')$('#main').innerHTML+=settingsPage();
 bindGuide();bindCareUI();bindTeam();
 const eventSelect=$('[name=activeEvent]');if(eventSelect)eventSelect.onchange=()=>chooseContext({missionID,eventID:eventSelect.value}).catch(e=>toast(e.message));
 const missionSelect=$('[name=activeMission]');if(missionSelect)missionSelect.onchange=()=>chooseContext({missionID:missionSelect.value}).catch(e=>toast(e.message));
 const searchInput=$('#guestSearch');if(searchInput)searchInput.oninput=()=>{search=searchInput.value;renderGuestList();};
 const idInput=$('#openGuestID');if(idInput)idInput.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();action('openform').catch(e=>toast(e.message));}};
 updateStatus();
}
function morePage(){const help={reports:'Activity and daily approval',inventory:'Grades, received and issued pairs',impact:'Approved results across missions',guide:'Practice and prepare for the trip',sync:'Saved entries and conflict review',settings:'Password, installation and notifications',team:'Volunteer accounts',audit:'Corrections for the selected day',appointments:'Schedule guest visits',programs:'Recipes and wellness activities'};return `<div class="more-grid">${navGroups.slice(1).filter(([,pages])=>pages.some(p=>allowed().includes(p))).map(([title,pages])=>`<section class="panel"><h2>${title}</h2><div class="menu-list">${pages.filter(p=>allowed().includes(p)).map(p=>`<a href="#${p}">${icon(p)}<span><strong>${labels[p]}</strong><small>${help[p]||pageHelp[p]||''}</small></span><span aria-hidden="true">→</span></a>`).join('')}</div></section>`).join('')}</div><div class="actions spaced">${button('password','Change my password','','secondary')}${button('prepare','Prepare my phone','','secondary')}${button('signout','Lock / sign out','','secondary')}</div>`;}

function cards(m){return `<div class="stats">${[['guests','People',m.guests],['glasses','Glasses pairs',m.glasses],['dental','Dental cleanings',m.dental],['assessments','Health assessments',m.assessments]].map(([key,label,value])=>`<button class="stat" data-action="daymetric" data-id="${key}"><div class="stat-top">${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${ev()?.approval==='approved'?'Approved day':'Current day · preliminary'} · View records →</div></button>`).join('')}</div>`;}

function dayOverview(){if(!ev())return welcomePage();const m=summarize(records());return `<section class="start-panel"><div><div class="eyebrow">Your daily workspace</div><h2>Ready for your next guest?</h2><p class="subtext">${esc(ev().location)} · ${esc(ev().starts)}. Every station connects through the guest’s ID.</p></div><div class="start-actions">${button('newregistration','Register a new guest')}${button('station','Enter a guest ID','','secondary')}<a href="#guests" class="text-button">Find a guest / recover an ID →</a></div></section>${!state.device?`<section class="prepare-banner"><div><strong>Get this phone ready before recording</strong><p class="subtext">Connect once to reserve IDs and prepare for offline work.</p></div>${button('prepare','Prepare this phone')}</section>`:''}<div class="section-heading"><h2>This day at a glance</h2><a href="#daily">Open daily report →</a></div>${cards(m)}<div class="grid-two"><section class="panel"><h2>Continue the day</h2><div class="menu-list"><a href="#daily">${icon('reports')}<span><strong>Daily report</strong><small>${m.registrations} registered · ${m.awaiting} awaiting registration</small></span><span>→</span></a><a href="#inventory">${icon('inventory')}<span><strong>Reading glasses stock</strong><small>Check available pairs by grade</small></span><span>→</span></a><a href="#events">${icon('events')}<span><strong>Missions & dates</strong><small>Choose another location or day</small></span><span>→</span></a></div></section><section class="panel"><h2>This phone</h2><p class="subtext">${state.device?'Ready for offline recording.':'Preparation needed before recording.'}</p><p class="subtext">${authorizedQueue().length} submissions awaiting sync or review.</p><p class="subtext">${state.lastSync?'Last sync: '+esc(new Date(state.lastSync).toLocaleString()):'Not synced yet'}</p><div class="actions spaced">${button('syncpage','Open sync center','','secondary')}<a href="#guide" class="text-button">Volunteer guide →</a></div></section></div>${admin()&&state.totals?`<section class="panel"><div class="section-heading"><h2>Across all approved days</h2><a href="#impact">View mission analysis →</a></div><p class="subtext">${state.totals.real.guests} people · ${state.totals.real.glasses} glasses pairs · ${state.totals.real.dental} dental cleanings. Draft days and samples are excluded.</p></section>`:''}`;}

function stationPage(){if(!ev())return welcomePage();return `<div class="guest-entry-grid"><section class="panel guest-entry"><div class="step-marker">GUEST HAS AN ID</div><h2>Continue a guest’s form</h2><p class="subtext">Use the ID on their slip. Then choose the station you’re recording.</p><label class="spaced" for="openGuestID">Guest ID<input id="openGuestID" placeholder="A0001" autocomplete="off" autocapitalize="characters" spellcheck="false"></label>${button('openform','Open guest form')}<a href="#guests" class="text-button spaced">Lost the slip? Find the guest’s ID →</a></section><section class="panel new-guest"><div class="step-marker">FIRST VISIT TODAY</div><h2>Register a new guest</h2><p class="subtext">Enter their personal details. The app creates the ID to use at every station.</p>${button('newregistration','New registration · generate ID','','secondary')}<p class="subtext">Already registered today? Use their existing ID to keep all records together.</p></section></div><details class="station-help"><summary>How the stations connect</summary><p class="subtext">Registration creates the ID. Every other station uses it, including offline. Entries join after the phones sync.</p><div class="station-tiles">${Object.values(STATIONS).map(s=>`<span>${esc(s)}</span>`).join('')}</div></details>`;}

function dailyGuestPage(){return `<section class="panel"><div class="panel-head"><div><h2>Guests & queue</h2><p>Joined by ID for this date and location. Unsynced records remain on their original phone.</p></div>${button('station','Open guest form','','secondary')}</div><label class="guest-search">Find a guest or recover a lost ID<input id="guestSearch" placeholder="Name, local name, phone, village or ID" value="${esc(search)}"></label><div id="guestList">${guestRows()}</div></section>`;}
function grouped(){const map=new Map();for(const r of records()){if(!map.has(r.guest_id))map.set(r.guest_id,{});map.get(r.guest_id)[r.station]=r;}return [...map.entries()].sort(([a],[b])=>displayID(a).localeCompare(displayID(b)));}
function guestRows(){const rows=grouped().filter(([id,r])=>[id,displayID(id),...Object.values(r).map(v=>JSON.stringify(v.data))].join(' ').toLowerCase().includes(search.toLowerCase()));return rows.map(([id,r])=>`<button class="guest-row" data-action="guest" data-id="${esc(id)}"><span class="avatar">${esc(r.registration?.data.name?.slice(0,2).toUpperCase()||'ID')}</span><span class="guest-info"><strong>${esc(r.registration?.data.name||(admin()?'Awaiting registration':'Guest ID record'))}</strong><small>${esc(r.registration?.data.local||'')} ${esc(r.registration?.data.village||'')}</small><span class="guest-code">${esc(displayID(id))}</span></span><span>${Object.keys(r).length} station${Object.keys(r).length===1?'':'s'}<br><small>${Object.values(r).some(v=>v.pending)?'Saved on phone':'Synced'}</small></span></button>`).join('')||empty('No matching records on this phone. Other phones must sync before their records appear for the team.');}
function renderGuestList(){if($('#guestList'))$('#guestList').innerHTML=guestRows();}
function show(title,body,submit,handler){$('#dialogBody').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button('close','Close','','text-button')}</div><form id="modalForm">${body}<p id="formStatus" role="status" aria-live="polite"></p>${submit?`<div class="modal-footer"><button type="submit" class="primary">${esc(submit)}</button></div>`:''}</form>`;$('#dialog').showModal();$('#dialog').scrollTop=0;if(handler)$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('[type=submit]');b.disabled=true;try{await handler(Object.fromEntries(new FormData(e.target)),e.target);}catch(err){$('#formStatus').textContent=err.message;}finally{b.disabled=false;}};}
function stationFields(st,d={}){
 const status=()=>select('record_status','Service status',['Completed','Waiting','Not required','Referred'],d.record_status||'Completed');
 if(st==='programs')return status()+select('education','Wellness education',['Not required','Completed','Waiting','Referred'],d.education)+select('juicing','Juicing program',['Not required','Completed','Waiting','Referred'],d.juicing)+select('detox','Detox / cleansing program',['Not required','Completed','Waiting','Referred'],d.detox)+field('other','Other activity',d.other)+select('other_status','Other activity status',['Not required','Completed','Waiting','Referred'],d.other_status)+area('notes','Activity notes',d.notes);
 if(st==='registration')return field('name','Full name',d.name,'text','required maxlength="150"')+field('local','Name in Lao / Thai',d.local)+field('age','Age',d.age,'number','min="0" max="120" step="1"')+select('sex','Sex',['Not recorded','Female','Male','Other'],d.sex)+field('phone','Phone',d.phone,'tel')+field('village','Village / district',d.village)+select('language','Language',['Lao','Thai','Hmong','English','Other'],d.language)+area('notes','Registration notes',d.notes);
 if(st==='measurements')return status()+field('height','Height (cm)',d.height,'number','min="30" max="250" step="0.1"')+field('weight','Weight (kg)',d.weight,'number','min="1" max="400" step="0.1"')+field('waist','Waistline (cm)',d.waist,'number','min="20" max="250" step="0.1"')+`<div class="full bmi-box">BMI: <strong id="bmiValue">${bmi(d)||'—'}</strong><small>Calculated from entered measurements.</small></div>`+area('notes','Measurement notes',d.notes);
 if(st==='glasses')return select('status','Glasses outcome',['Provided','Assessed only','Referred','Waiting','Not required'],d.status)+select('grade','Reading glasses grade',state.grades.map(g=>[g.grade,'+'+g.grade+' · '+remaining(g.grade)+' pairs remaining']),d.grade||'1.00')+field('quantity','Pairs provided',d.quantity||'1','number','min="0" max="20" step="1"')+area('notes','Glasses notes',d.notes);
 if(st==='dental')return select('status','Dental outcome',['Completed','Assessed only','Referred','Declined','Waiting','Not required'],d.status)+area('notes','Dental notes',d.notes);
 if(st==='consultation')return status()+field('followup_date','Follow-up date',d.followup_date,'date')+area('reason','Reason for consultation',d.reason)+area('findings','Clinician findings',d.findings)+area('diagnoses','Confirmed diagnosis / source',d.diagnoses)+area('advice','Advice / follow-up',d.advice)+select('referral','Referral',['Not recorded','No','Yes'],d.referral)+field('clinician','Clinician / consultant',d.clinician)+area('notes','Consultation notes',d.notes);
 return field('systolic','Blood pressure: systolic (mmHg)',d.systolic,'number','min="40" max="300"')+field('diastolic','Blood pressure: diastolic (mmHg)',d.diastolic,'number','min="20" max="200"')+field('sugar','Blood sugar',d.sugar,'number','min="0.1" max="1000" step="0.1"')+select('sugarUnit','Blood sugar unit',['mg/dL','mmol/L'],d.sugarUnit)+select('sugarContext','Blood sugar context',['Not recorded','Fasting','Random','After meal'],d.sugarContext)+field('uric','Uric acid',d.uric,'number','min="0.1" max="1000" step="0.1"')+select('uricUnit','Uric acid unit',['mg/dL','µmol/L'],d.uricUnit)+area('symptoms','Symptoms reported by guest',d.symptoms)+area('diagnoses','Confirmed diagnosis / clinician source',d.diagnoses)+area('allergies','Allergies',d.allergies)+area('medications','Current medication',d.medications)+select('referral','Referral needed / arranged',['Not recorded','No','Yes'],d.referral)+area('notes','Assessment / referral details',d.notes);
}
async function stationForm(st=station,id='',record=null,alternate=false,prefill={}){canWork();if(!assigned().includes(st))throw Error('Unknown station.');if(record&&!admin())throw Error('Sub-users can create records only. Ask an administrator for a correction.');
 const currentEvent=eventID,currentSession={...ev()};
 if(!id){if(st!=='registration')throw Error('Enter the guest ID first.');await ensureTickets();await vault.edit(s=>{id=reserveTicket(s,missionID);});state=vault.state;}
 show((record?'Correct ':'')+STATIONS[st],`${note(esc(ev().starts)+' · '+esc(ev().location)+(ev().sample?' · Fictional sample event':''))}<div class="form-grid">${st==='registration'&&!id?note('A unique guest ID is assigned only after this phone safely saves the registration.'):field('guest_id','Guest ID',displayID(id),'text',`required autocomplete="off" autocapitalize="characters" ${id?'readonly':''}`)}${st==='registration'?`<input type="hidden" name="person_id" value="${esc(record?.data.person_id||prefill.person_id||id)}">`:''}${stationFields(st,record?.data||prefill)}</div>`,'Save on this phone',async(data)=>{
  const gid=id;delete data.guest_id;if(st==='registration'){const m=state.missions.find(m=>m.id===currentSession.mission_id);data.country=m?.country||currentSession.country||'Laos';data.province=m?.province||'';}const clean=validateData(st,data);if(!state.events.some(e=>e.id===currentEvent&&!e.closed))throw Error('This session was closed or your access changed. Your form has not been saved.');const mismatch=currentSession.starts!==date();if(mismatch&&!confirm('Date warning: this session is '+currentSession.starts+' at '+currentSession.location+', but today is '+date()+'. Save here anyway?'))return;if(gid&&!validID(gid))throw Error('Check the guest ID on the slip.');
  let saved;
  await vault.edit(s=>{if(s.deviceId!==s.device?.id)throw Error('Phone identity changed. Prepare it again.');const guestID=gid;const existing=mergeRecords(s.snapshots[currentEvent]?.records||[],s.queue).find(r=>r.event_id===currentEvent&&r.guest_id===guestID&&r.station===st);if(existing&&!record&&!alternate)throw Error('This station already has a record for this guest. Ask an administrator to review it.');if(existing?.pending)throw Error('Sync the saved record before correcting it.');saved={id:crypto.randomUUID(),event_id:currentEvent,guest_id:guestID,station:st,data:clean,device_id:s.device.id,author:s.user.id,base_revision:record?.revision||null,status:'pending',created_at:new Date().toISOString(),captured_at:new Date().toISOString(),date_ack:mismatch};s.queue.push(saved);});
  state=vault.state;$('#dialog').close();render();show('Saved on this phone',`<p>Write this guest ID on the paper slip.</p><div class="id-slip">${esc(displayID(saved.guest_id,currentEvent))}</div><p>${esc(clean.name||STATIONS[st])}</p><p class="subtext">${esc(ev()?.name)} · ${navigator.onLine?'Syncing when a connection is available.':'Offline — safely queued on this phone.'}</p><div class="actions spaced">${st==='registration'?button('nextregistration','Next guest'):button('nextstation','Next guest',st)}${button('copyid','Copy ID',saved.guest_id,'secondary')}${button('printid','Print ID slip',saved.guest_id,'secondary')}${button('conflictguest','Open complete form',saved.guest_id,'secondary')}</div>`,null);sync();
 });
 if(st==='measurements')$('#modalForm').oninput=()=>{const d=Object.fromEntries(new FormData($('#modalForm')));$('#bmiValue').textContent=bmi(d)||'—';};
}
function guestDetail(id){if(!validID(id))throw Error('Enter the guest ID from the slip, for example A0001.');const row=grouped().find(([g])=>g===id)?.[1]||{};show(row.registration?.data.name||'Guest form',`<div class="id-slip">${esc(displayID(id))}</div><p class="subtext">${esc(ev()?.starts)} · ${esc(ev()?.location)}</p>${button('copyid','Copy / recover ID',id,'secondary')}${!row.registration?note('Registration has not reached this phone yet. Other stations can still save with this ID.'):''}<div class="guest-station-grid">${Object.entries(STATIONS).map(([st,label])=>{const r=row[st];return `<section class="record-section guest-station"><h3>${label}</h3>${r?`<details><summary>${esc(recordStatus(r))} · ${r.pending?'Saved on phone':'View details'}</summary><p class="subtext">${r.pending?'Saved on phone':'Synced'} · ${esc(state.members.find(m=>m.id===r.author)?.name||'Mission team')}</p><dl class="summary-grid">${Object.entries(r.data).filter(([k,v])=>v&&!['person_id','consent','address'].includes(k)).map(([k,v])=>`<dt>${esc(fieldLabel(k))}</dt><dd>${esc(v)}</dd>`).join('')}${st==='measurements'?`<dt>BMI</dt><dd>${bmi(r.data)}</dd>`:''}</dl>${!r.pending&&!ev()?.closed?(admin()?button('editrecord','Correct record',id+'|'+st,'secondary'):button('alternate','Submit a different record for review',id+'|'+st,'secondary')):''}</details>`:`<p class="subtext"><span class="status-pill waiting">Waiting</span> Not yet recorded on this phone.</p>${!ev()?.closed?button('addsection','Record '+label,id+'|'+st):''}`}</section>`}).join('')}</div>`,null);}
function welcomePage(){return `<section class="hero"><div><div class="eyebrow">Welcome, ${esc(state.user.name)}</div><h2>Your next mission starts here.</h2><p>Join your team using the mission code from your leader. Each day and location has its own guest forms, stock and report.</p><div class="actions spaced">${button('joinmission','Enter mission code')}${button('guide','Practice before the trip','','secondary')}${admin()?button('missionform','Create mission','','secondary'):''}</div></div></section><div class="grid-two"><section class="panel"><h2>Before travelling</h2><p class="subtext">Join the mission, open its calendar and prepare this phone while online. Each phone receives a unique ID prefix automatically.</p></section><section class="panel"><h2>At the event</h2><p class="subtext">Use the guest ID at every station. Save offline, then sync before the day is reviewed. Your team’s daily progress is visible inside the mission.</p></section></div>`;}
function missionForm(id){const m=state.missions.find(m=>m.id===id)||{};show(id?'Event details':'Create an event',`<div class="form-grid">${id?`<input type="hidden" name="kind" value="${esc(m.kind||'large')}"><p class="notice">${m.kind==='regular'?'Regular visits':'Large event'}</p>`:select('kind','Classification',[['large','Large event'],['regular','Regular visits']],'large')}${(m.kind==='regular'?field('location','Regular-visit default location',m.location||'Oon Jai Wellness'):'')}${select('country','Country',['Laos','Thailand','Other'],m.country||'Laos')}${field('province','Province',m.province,'text','maxlength="120"')}${field('name','Event name',m.name,'text','required placeholder="March 2027 mission trip"')}${field('code','Shared mission code',m.code,'text','required minlength="4" maxlength="50" placeholder="MT-03-2027" autocapitalize="characters"')}${select('active','Allow new members',[['true','Yes'],['false','No']],String(m.active!==false))}${area('notes','Mission notes',m.notes)}</div>`,'Save event',async d=>{const savedID=id||crypto.randomUUID();await api('mission',{mission:{...d,id:savedID,revision:m.revision,code:d.code.trim().toUpperCase(),active:d.active==='true'}});await refreshAccess();$('#dialog').close();if(d.kind!=='regular')await enterEvent(savedID);else render();});}
function eventForm(id){const e=state.events.find(x=>x.id===id)||{};if(!state.missions.length)return missionForm();show(id?'Edit daily session':'Add day and location',`${note('Create a separate session for every date and location, including two days at the same venue.')}<div class="form-grid">${focusedMissionID?`<input type="hidden" name="mission_id" value="${esc(focusedMissionID)}">`:select('mission_id','Event',state.missions.map(m=>[m.id,m.name]),e.mission_id||missionID)}${field('name','Session name',e.name,'text','required placeholder="Community outreach"')}${field('starts','Session date',e.starts||date(),'date','required')}${field('location','Location / venue / village',e.location,'text','required')}${area('notes','Notes',e.notes)}</div>`,'Save day',async d=>{const savedID=id||crypto.randomUUID();await api('event',{event:{...d,country:state.missions.find(m=>m.id===d.mission_id)?.country||'Laos',id:savedID,revision:e.revision,ends:d.starts,closed:e.closed||false}});await refreshAccess();$('#dialog').close();if(focusedMissionID)await chooseContext({missionID:focusedMissionID,eventID:savedID});else render();});}
function serviceChart(m){const values=[['Registered',m.registrations],['Reading glasses',m.glassesPeople],['Dental cleaning',m.dental],['Health assessments',m.assessments],['Blood pressure',m.bp],['Blood sugar tests',m.sugar],['Uric acid tests',m.uric],['Wellness activities',m.activities],['Consultations',m.consultations],['Glasses + dental',m.both]];const max=Math.max(1,...values.map(v=>v[1]));return `<div class="service-chart" role="img" aria-label="Daily service counts: ${esc(values.map(v=>v.join(' ')).join(', '))}">${values.map(([label,n])=>`<div><span>${label}</span><i><b style="width:${n/max*100}%"></b></i><strong>${n}</strong></div>`).join('')}</div>`;}
function dailyReportPage(){const rs=records(),m=summarize(rs);return cards(m)+`<section class="panel"><div class="panel-head"><h2>Daily assessment · ${ev()?.approval==='approved'?'approved':'preliminary'}</h2>${admin()?button('approve',ev()?.approval==='approved'?'Reopen day':'Review & approve day','','secondary'):''}${button('export','Export daily CSV','','secondary')}</div><p class="subtext">${esc(ev()?.name||'Choose an event')} · All stations for this date and location. Only approved real days enter main totals.</p><dl class="summary-grid"><dt>Registration records</dt><dd>${m.registrations}</dd><dt>Waiting for registration</dt><dd>${m.awaiting}</dd><dt>Height & weight / BMI</dt><dd>${m.measurements}</dd><dt>Health assessments</dt><dd>${m.assessments}</dd><dt>Blood pressure checks</dt><dd>${m.bp}</dd><dt>Blood sugar tests</dt><dd>${m.sugar}</dd><dt>Uric acid tests</dt><dd>${m.uric}</dd><dt>Wellness activities</dt><dd>${m.activities}</dd><dt>Follow-ups</dt><dd>${m.followups}</dd><dt>Consultations</dt><dd>${m.consultations}</dd><dt>Reading glasses recipients</dt><dd>${m.glassesPeople}</dd><dt>Both glasses and dental</dt><dd>${m.both}</dd><dt>Consultation without glasses / dental</dt><dd>${m.consultationOnly}</dd><dt>Referral recorded</dt><dd>${m.referrals}</dd><dt>Submissions needing review</dt><dd>${snap().conflicts?.length||0}</dd></dl>${serviceChart(m)}${note('Assessment summaries report what the team entered. The app does not generate diagnoses.')}<div class="table-wrap"><table><thead><tr><th>Guest / ID</th>${Object.values(STATIONS).map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${grouped().map(([id,r])=>`<tr><td><button class="text-button" data-action="guest" data-id="${esc(id)}">${esc(r.registration?.data.name||'Awaiting registration')}<br>${esc(displayID(id))}</button></td>${Object.keys(STATIONS).map(st=>`<td>${r[st]?(st==='measurements'&&recordStatus(r[st])==='Completed'?'BMI '+bmi(r[st].data):st==='glasses'?esc(r[st].data.status)+' · '+esc(r[st].data.quantity||0):st==='dental'?esc(r[st].data.status):esc(recordStatus(r[st]))):'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
let teamMission='',teamDay='';const attendanceDraft=new Map();
function teamPage(){
 if(focused())teamMission=focusedMissionID;
 if(teamMission&&!state.missions.some(m=>m.id===teamMission))teamMission='';
 const days=state.events.filter(e=>e.mission_id===teamMission).sort((a,b)=>b.starts.localeCompare(a.starts));
 if(!days.some(e=>e.id===teamDay))teamDay=days.find(e=>e.id===eventID)?.id||days[0]?.id||'';
 const memberships=(state.teamMemberships||[]).filter(mm=>(mm.active!==false||teamMission&&(state.attendance||[]).some(a=>a.event_id===teamDay&&a.user_id===mm.user_id))&&(!teamMission||mm.mission_id===teamMission));
 const people=(admin()?state.members:state.roster||[]).filter(m=>!teamMission||memberships.some(mm=>mm.user_id===m.id));
 const attendance=(state.attendance||[]).filter(a=>a.event_id===teamDay);
 return `<section class="panel"><div class="panel-head"><div><h2>${teamMission?esc(state.missions.find(m=>m.id===teamMission)?.name)+' · team':'Volunteer teams'}</h2><p>${admin()?'Add a whole group, manage authority and record attendance by day and location.':'Your mission teams. Account settings and authority changes are managed by an administrator.'}</p></div>${admin()?button('createuser','Add volunteers'):''}</div><div class="form-grid spaced">${focused()?'':select('teamMission','Mission trip',[['',admin()?'All accounts':'My mission teams'],...state.missions.map(m=>[m.id,m.name])],teamMission)}${teamMission?select('teamDay','Attendance · day & location',days.length?days.map(e=>[e.id,e.starts+' · '+e.location]):[['','No days scheduled']],teamDay):''}</div>${!teamMission?`<div class="team-trip-grid spaced">${state.missions.map(m=>`<button class="secondary team-trip" data-team-mission="${esc(m.id)}"><strong>${esc(m.name)}</strong><span>${(state.teamMemberships||[]).filter(mm=>mm.mission_id===m.id&&mm.active!==false).length} team members</span></button>`).join('')}</div>`:''}<div class="actions spaced">${teamMission&&admin()?button('teamadd','Add existing accounts to trip','','secondary'):''}${teamMission&&teamDay&&admin()?button('teamsave','Save attendance'):''}${teamMission&&teamDay?button('teamexport','Export attendance','','secondary'):''}</div>${teamMission&&teamDay?note(`${attendance.filter(a=>a.status==='present').length} present · ${attendance.filter(a=>a.status==='absent').length} absent · ${attendance.filter(a=>a.status==='excused').length} excused. Unmarked people have not been recorded as attending.`):''}<div class="team-list">${people.map(m=>{const status=attendanceDraft.get(teamDay+'|'+m.id)||attendance.find(a=>a.user_id===m.id)?.status||'unmarked',joined=memberships.find(mm=>mm.user_id===m.id&&mm.mission_id===teamMission);return `<article class="team-person"><span class="avatar">${esc(m.initials||m.name.slice(0,2).toUpperCase())}</span><div class="guest-info"><strong>${esc(m.name)}</strong>${admin()?`<small>${esc(m.email)}</small><span class="badge">${m.role==='admin'?'Administrator':'Volunteer'} · ${esc(m.status)}</span>`:''}${joined?`<small>${joined.active===false?'Former team member · ':''}Joined ${esc(new Date(joined.joined_at).toLocaleDateString())}</small>`:''}</div><div class="team-controls">${teamMission&&teamDay?(admin()&&joined?.active!==false?select('attendance_'+m.id,'Attendance',[['unmarked','Not marked'],['present','Present'],['absent','Absent'],['excused','Excused']],status):`<span class="badge">${esc(status==='unmarked'?'Not marked':status)}</span>`):''}${admin()?button('memberform','Authority & status',m.id,'secondary'):''}${admin()&&teamMission&&joined?.active!==false?button('teamremove','Remove from trip',m.id,'text-button'):''}</div></article>`;}).join('')||empty('No team members here yet. An administrator can add a group to this trip.')}</div></section>`;
}
function bindTeam(){
 $$('[name^=attendance_]').forEach(el=>el.onchange=()=>attendanceDraft.set(teamDay+'|'+el.name.slice(11),el.value));
 const mission=$('[name=teamMission]'),day=$('[name=teamDay]');if(mission)mission.onchange=()=>{teamMission=mission.value;teamDay='';render();};if(day)day.onchange=()=>{teamDay=day.value;render();};
 $$('[data-team-mission]').forEach(b=>b.onclick=()=>{teamMission=b.dataset.teamMission;teamDay='';render();});
}
function addMissionMembers(){if(!admin()||!teamMission)throw Error('Choose a mission trip first.');const ids=new Set((state.teamMemberships||[]).filter(m=>m.mission_id===teamMission&&m.active!==false).map(m=>m.user_id)),people=state.members.filter(m=>!ids.has(m.id)&&m.status==='active');show('Add team members',`<p>Select existing accounts for this trip. Their access starts when added.</p>${people.map(m=>`<label class="checkline"><input type="checkbox" name="member" value="${esc(m.id)}">${esc(m.name)} · ${esc(m.email)}</label>`).join('')||empty('All active accounts are already on this team.')}`,'Add selected',async(d,form)=>{const user_ids=new FormData(form).getAll('member');if(!user_ids.length)throw Error('Select at least one account.');await api('team-assign',{mission_id:teamMission,user_ids});await refreshAccess();$('#dialog').close();render();});}
async function saveAttendance(){const rows=$$('[name^=attendance_]').map(el=>({user_id:el.name.slice(11),status:el.value}));if(!rows.length)throw Error('Add people to this team first.');await api('attendance',{event_id:teamDay,rows});for(const r of rows)attendanceDraft.delete(teamDay+'|'+r.user_id);await refreshAccess();render();toast('Attendance saved for this day and location.');}
function exportAttendance(){const e=state.events.find(e=>e.id===teamDay),mission=state.missions.find(m=>m.id===teamMission),people=admin()?state.members:state.roster;downloadCSV([['Mission trip','Date','Location','Full name','Attendance'],...(state.teamMemberships||[]).filter(mm=>mm.mission_id===teamMission&&(mm.active!==false||state.attendance.some(a=>a.event_id===teamDay&&a.user_id===mm.user_id))).map(mm=>[mission?.name,e?.starts,e?.location,people.find(m=>m.id===mm.user_id)?.name||'',state.attendance.find(a=>a.event_id===teamDay&&a.user_id===mm.user_id)?.status||'Not marked'])],'Wellness-team-attendance.csv');}
function bulkVolunteerForm(){
 if(!admin())throw Error('Administrator access required.');const batch_id=crypto.randomUUID();let rows=Array.from({length:10},()=>({name:'',email:''})),results=[];
 const draw=()=>{show('Add volunteers',`${note('Enter full names and emails. New accounts get individual temporary passwords and must choose a new password at first login. Existing accounts keep their passwords.')}<div class="form-grid">${select('batchMission','Assign to mission trip',[['','No trip yet'],...state.missions.filter(m=>m.active).map(m=>[m.id,m.name])],teamMission||focusedMissionID)}</div><div id="bulkRows" class="bulk-rows">${rows.map((r,i)=>`<div class="bulk-row"><span>${i+1}</span>${field('name_'+i,'Full name',r.name,'text','maxlength="120" autocomplete="off"')}${field('email_'+i,'Email',r.email,'email','autocomplete="off"')}</div>`).join('')}</div><div class="actions spaced"><button type="button" class="secondary" id="bulkAddRow">Add another row</button></div><details class="spaced"><summary>Paste a list from a spreadsheet</summary>${area('pastePeople','One full name and email per line, separated by a tab or comma')}<button type="button" class="secondary" id="bulkPaste">Fill rows from list</button></details>`,'Save volunteers',async(d,form)=>{
  const people=normalizePeople(rows.map((r,i)=>({name:d['name_'+i],email:d['email_'+i]})).filter(r=>r.name.trim()||r.email.trim()));
  $('#formStatus').textContent='Creating accounts. Keep this window open…';
  const selected=d.batchMission;const response=await api('create-users',{people,batch_id,mission_id:selected||null});results=response.results;await refreshAccess();$('#dialog').close();render();showResults(selected);
 });$('#bulkAddRow').onclick=()=>{if(rows.length>=50){toast('Save this batch before adding more than 50 people.');return;}readRows();rows.push({name:'',email:''});draw();};$('#bulkPaste').onclick=()=>{try{const text=$('[name=pastePeople]').value;rows=normalizePeople(text.split(/\r?\n/).filter(x=>x.trim()).map(line=>{const parts=line.split(/\t|,/).map(x=>x.trim());return {name:parts.slice(0,-1).join(' '),email:parts.at(-1)};}));readMission();draw();}catch(e){$('#formStatus').textContent=e.message;}};};
 const readMission=()=>{teamMission=$('[name=batchMission]').value;};const readRows=()=>{readMission();rows=rows.map((r,i)=>({name:$('[name=name_'+i+']').value,email:$('[name=email_'+i+']').value}));};
 const showResults=selected=>{show('Volunteer accounts',`${note('Give each new person their own temporary password privately. These passwords are shown only in this result and are not saved on this phone.')}<div class="bulk-results">${results.map(r=>`<article class="record-section"><h3>${esc(r.name)}</h3><p>${esc(r.email)} · <strong>${esc(r.status)}</strong></p>${r.temporary_password?`<p>Temporary password: <code>${esc(r.temporary_password)}</code></p>`:''}<p class="subtext">${esc(r.message)}</p></article>`).join('')}</div><div class="actions"><button type="button" class="secondary" id="downloadLogins">Download login list</button>${results.some(r=>r.status==='error')?'<button type="button" class="primary" id="retryPeople">Retry unsuccessful rows</button>':''}</div>`,null);$('#downloadLogins').onclick=()=>downloadCSV([['Full name','Email','Temporary password','Result','Instructions'],...results.map(r=>[r.name,r.email,r.temporary_password||'',r.status,r.message])],'Wellness-volunteer-logins.csv');const retry=$('#retryPeople');if(retry)retry.onclick=async()=>{retry.disabled=true;try{const next=await api('create-users',{people:results.filter(r=>r.status==='error').map(r=>({name:r.name,email:r.email})),batch_id,mission_id:selected||null});results=results.map(r=>next.results.find(n=>n.email===r.email)||r);await refreshAccess();$('#dialog').close();render();showResults(selected);}catch(e){$('#formStatus').textContent=e.message;}finally{retry.disabled=false;}};};draw();
}
function memberForm(id){if(!admin())throw Error('Administrator access required.');const m=state.members.find(m=>m.id===id);show('Authority & status · '+m.name,`${note('Administrators can see all Wellness data and manage accounts. Volunteers see their assigned trips and records from when they joined.')}<p>${esc(m.email)}</p><div class="form-grid">${select('role','Authority',[['volunteer','Volunteer'],['admin','Administrator · all Wellness data']],m.role)}${select('status','Account status',['active','pending','disabled'],m.status)}</div>`,'Save access',async d=>{if(d.role==='admin'&&m.role!=='admin'&&!confirm('Give '+m.name+' administrator access to all Wellness events, records and account controls?'))return;await api('member',{id,status:d.status,role:d.role});await refreshAccess();$('#dialog').close();render();});}
function appointmentPage(){const list=snap().resources.filter(r=>r.kind==='appointment');return `<div class="actions spaced">${admin()?button('appointment','Schedule appointment'):''}</div><div class="event-grid">${list.map(r=>`<section class="panel"><span class="badge">${esc(r.data.status)}</span><h2>${esc(r.data.name)}</h2><p class="subtext">${esc(r.data.date)} ${esc(r.data.time)}<br>${esc(r.data.service)}<br>${esc(r.data.location)}</p>${admin()?button('appointment','Edit appointment',r.id,'secondary'):''}</section>`).join('')||empty('No appointments for this event.')}</div>`;}
function appointmentForm(id){const r=snap().resources.find(r=>r.id===id),d=r?.data||{};show('Appointment',`<div class="form-grid">${field('name','Guest name',d.name,'text','required')}${field('guest_id','Guest ID (if known)',d.guest_id)}${field('date','Date',d.date||date(),'date','required')}${field('time','Time',d.time||'09:00','time','required')}${select('service','Service',Object.values(STATIONS),d.service)}${select('status','Status',['Scheduled','Completed','Cancelled','Did not attend'],d.status)}${field('location','Location',d.location||ev()?.location)}${area('notes','Notes',d.notes)}</div>`,'Save appointment',async data=>{await api('resource',{resource:{id:id||crypto.randomUUID(),kind:'appointment',event_id:eventID,data,revision:r?.revision}});$('#dialog').close();await sync();});}
function programPage(){return `<div class="actions spaced">${admin()?button('recipe','Add recipe'):''}</div><div class="event-grid">${snap().resources.filter(r=>r.kind==='recipe').map(r=>`<section class="panel"><span class="badge">${esc(r.data.category)}</span><h2>${esc(r.data.name)}</h2><p class="subtext">${esc(r.data.description)}</p><p class="subtext">${esc(r.data.servings)} servings · ${esc(r.data.size)} ml each</p><div class="actions spaced">${button('recipeview','View / scale',r.id)}${admin()?button('recipe','Edit',r.id,'secondary'):''}</div></section>`).join('')||empty('No recipes saved yet.')}</div>`;}
function recipeForm(id){const r=snap().resources.find(r=>r.id===id),d=r?.data||{};show('Program recipe',`<div class="form-grid">${field('name','Recipe name',d.name,'text','required')}${select('category','Category',['Juicing','Wellness education','Detox / cleansing'],d.category)}${field('servings','Base servings',d.servings||'2','number','required min="1" max="10000"')}${field('size','Serving size (ml)',d.size||'250','number','required min="1"')}${area('description','Description',d.description)}${area('ingredients','Ingredients: one per line, ingredient | quantity | unit',d.ingredients)}${area('instructions','Preparation instructions',d.instructions)}${area('allergens','Allergens / ingredient cautions',d.allergens)}</div>`,'Save recipe',async data=>{await api('resource',{resource:{id:id||crypto.randomUUID(),kind:'recipe',event_id:null,data,revision:r?.revision}});$('#dialog').close();await sync();});}
function recipeView(id){const d=snap().resources.find(r=>r.id===id)?.data;if(!d)return;show(d.name,`${field('scale','Number of servings',d.servings,'number','min="1" max="10000"')}<div id="ingredients"></div><h3>Preparation</h3><p class="prewrap">${esc(d.instructions)}</p>${note(esc(d.allergens))}`,null);const paint=()=>{const scale=Number($('#modalForm [name=scale]').value)/Number(d.servings);$('#ingredients').innerHTML=`<ul>${String(d.ingredients).split('\n').map(line=>{const [name,q,unit]=line.split('|');return `<li>${esc(name)} · ${Number.isFinite(+q*scale)?(+q*scale).toFixed(1):esc(q)} ${esc(unit)}</li>`}).join('')}</ul>`;};$('#modalForm [name=scale]').oninput=paint;paint();}
function auditPage(){return `<section class="panel"><h2>Corrections and edits</h2><p class="subtext">New submissions are excluded. Latest 500 event edits.</p>${snap().audit.map(a=>`<details class="record-section"><summary>${esc(a.station)} · ${esc(a.guest_id||'Event')} · ${esc(new Date(a.created_at).toLocaleString())}</summary><p>${esc(state.members.find(m=>m.id===a.actor)?.name||'Team')}</p><div class="grid-two"><pre>${esc(JSON.stringify(a.before_data,null,2))}</pre><pre>${esc(JSON.stringify(a.after_data,null,2))}</pre></div></details>`).join('')||empty('No edits recorded for this event.')}</section>`;}
function settingsPage(){return `<div class="grid-two"><section class="panel"><h2>This phone</h2><p class="subtext">${esc(state.user.email)}<br>User ID: ${esc(state.user.id)}</p><p class="subtext">${state.device?'Phone code: '+esc(state.device.prefix)+'-'+String(state.device.code).padStart(4,'0'):'Not prepared yet'}</p><div class="actions spaced">${button('prepare','Prepare / refresh phone')}${button('password','Change password','','secondary')}</div>${note('Before travelling: sign in online, join the mission, select the day and location, prepare the phone, then test it in airplane mode. Offline access lasts 7 days after the last access refresh. Pending records stay saved until synced.')}</section><section class="panel"><h2>App & notifications</h2><div class="actions spaced"><a class="secondary" href="#guide">Volunteer guide</a><a class="secondary" href="#sync">Sync center</a></div><p class="subtext">Install this app from your browser menu for faster access.</p>${button('install','Install app','','secondary')}${admin()?button('pushenable','Enable administrator notifications','','secondary')+button('pushtest','Send a test notification','','secondary')+button('pushdisable','Disable notifications here','','text-button'):''}${button('checkupdates','Check for updates','','secondary')}<p id="updateStatus" class="subtext">Wellness 1.3.0</p></section></div>`;}
function syncPage(){return `<section class="panel"><div class="panel-head"><h2>Saved on this phone</h2>${button('sync','Retry sync','','secondary')}</div>${note('Keep this phone’s browser data until every submission is synced. Closing or restarting the app keeps saved entries. Internet access is needed only for preparation, sign-up, password recovery and synchronization.')} ${visibleQueue().map(o=>`<article class="record-section"><h3>${esc(displayID(o.guest_id,o.event_id))} · ${STATIONS[o.station]}</h3><span class="badge">${esc(o.status)}</span><p class="subtext">${esc(o.error||'Waiting for connection')}</p><p class="subtext">${esc(state.events.find(e=>e.id===o.event_id)?.name||'Event access changed')}</p></article>`).join('')||empty('All submissions from this phone are synced.')}</section>${admin()?`<section class="panel spaced"><h2>Event conflicts · administrator review</h2>${snap().conflicts.map(c=>`<article class="record-section"><h3>${esc(displayID(c.operation.guest_id,c.operation.event_id))} · ${esc(STATIONS[c.operation.station])}</h3><p class="subtext">${esc(state.members.find(m=>m.id===c.user_id)?.name||'Volunteer')}</p><pre>${esc(JSON.stringify(c.operation.data,null,2))}</pre><div class="actions">${button('reviewconflict','Compare / correct',c.id)}${button('resolveconflict','Keep current record',c.id,'secondary')}</div></article>`).join('')||empty('No event conflicts.')}</section>`:''}`;}
function exportCSV(){const rows=[['Event','Event ID','Guest ID','Station','Field','Value','Author','Saved at']];for(const r of records())for(const [k,v]of Object.entries(r.data).filter(([k])=>!['person_id','consent','address'].includes(k)))rows.push([ev()?.name,eventID,displayID(r.guest_id,r.event_id),STATIONS[r.station],k,v,state.members.find(m=>m.id===r.author)?.name||r.author,r.updated_at||r.created_at]);const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='Wellness-event-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function legacyRemaining(grade){const opening=Number(snap().stock?.find(s=>s.grade===grade)?.received||0);const issued=records().filter(r=>r.station==='glasses'&&r.data.grade===grade&&r.data.status==='Provided').reduce((n,r)=>n+Number(r.data.quantity||0),0);return opening-issued;}
function approveDay(){if(state.queue.some(o=>o.event_id===eventID&&!['conflict','reviewed'].includes(o.status)))throw Error('Sync this phone’s pending entries before reviewing the day.');if(!ev())throw Error('Choose a day first.');const approved=ev().approval==='approved';show(approved?'Reopen approved day':'Daily review and approval',`${note(approved?'Reopening removes this day from the main approved totals until you approve it again.':'Check the daily report, resolve conflicts, recover missing registration details and reconcile stock. Every field phone must sync before approval.')}<dl class="summary-grid"><dt>Date</dt><dd>${esc(ev().starts)}</dd><dt>Location</dt><dd>${esc(ev().location)}</dd><dt>Reported phones</dt><dd>${snap().devices?.length||0}</dd><dt>Pending reported by phones</dt><dd>${(snap().devices||[]).reduce((n,d)=>n+d.pending,0)}</dd><dt>Unresolved conflicts</dt><dd>${snap().conflicts?.length||0}</dd></dl>${!approved?`<label class="checkline"><input type="checkbox" name="phones_confirmed" required>I checked with the team: all phones have synced and this day is ready.</label><p class="subtext">A phone that has not connected cannot report its unsynced entries. This confirmation is required before adding results to the main totals.</p>`:''}`,approved?'Reopen day':'Approve day',async d=>{await api('approve',{event_id:eventID,approved:!approved,phones_confirmed:d.phones_confirmed==='on'});$('#dialog').close();await sync();});}
function alertsView(){show('Administrator alerts',`${note('All administrator accounts see unresolved conflicts on refresh. No earlier record is overwritten. Open the affected day to compare both submissions.')} ${(state.alerts||[]).filter(a=>!focused()||state.events.some(e=>e.id===a.operation.event_id&&e.mission_id===focusedMissionID)).map(a=>`<article class="record-section"><h3>${esc(displayID(a.operation.guest_id,a.operation.event_id))} · ${esc(STATIONS[a.operation.station])}</h3><p>${esc(state.events.find(e=>e.id===a.operation.event_id)?.name||'Session')}</p>${button('alertday','Review this day',a.operation.event_id,'secondary')}</article>`).join('')||empty('No unresolved conflicts.')}`,null);}
async function action(name,id){
 if(name==='close'){$('#dialog').close();return;}
 if(name==='login'||name==='signup'||name==='forgot'){authView(name);return;}
 if(name==='offline'){await offline();return;}
 if(name==='resend'){const email=$('#loginForm [name=email]').value;if(!email)throw Error('Enter your email first.');const {error}=await sb.auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin+location.pathname}});if(error)throw error;message('Verification email requested. Confirm your email, then return here.');return;}
 if(name==='signout'){if(state?.queue.length&&!confirm('Your unsynced entries will stay encrypted on this phone. Lock and sign out?'))return;await navigator.locks.request('wellness-sync-'+vault.email,async()=>{await sb.auth.signOut({scope:'local'});vault.close();state=null;missionID='';eventID='';focusedMissionID='';search='';$('#dialog').close();authView();});return;}
 if(!state)throw Error('Sign in first.');
 if(await careAction(name,id))return;
 if(name==='sync')return sync();if(name==='prepare')return prepare();
 if(name==='station'||name==='viewrecords'||name==='report'||name==='syncpage'){location.hash=({station:'stations',viewrecords:'guests',report:'daily',syncpage:'sync'})[name];return;}
 if(name==='stationform'||name==='newregistration')return stationForm('registration');
 if(name==='openform'){const id=lookupID($('#openGuestID').value);if(!validID(id))throw Error('Enter the complete guest ID before proceeding.');return guestDetail(id);}
 if(name==='addsection'||name==='alternate'){const [gid,st]=id.split('|');$('#dialog').close();return stationForm(st,gid,null,name==='alternate');}
 if(name==='joinmission')return show('Join a mission',`${field('code','Mission code','','text','required placeholder="MT-03-2027" autocapitalize="characters"')}<p class="subtext">Your leader provides the code. It opens this mission’s dates and records from when you join. Earlier events and records stay restricted.</p>`,'Join mission',async d=>{const r=await api('join',{code:d.code.trim().toUpperCase()});await refreshAccess();await chooseContext({missionID:r.mission_id});$('#dialog').close();location.hash='events';render();if(eventID)await prepare();});
 if(name==='missionform')return missionForm(id);
 if(name==='missions'){location.hash='events';return;}if(name==='guide'){location.hash='guide';return;}if(name==='impact'){location.hash='impact';return;}if(name==='impactexport')return exportUnified();
 if(name==='stockform')return stockForm();
 if(name==='gradeform')return show('Add glasses grade',field('grade','Grade','','number','required min="0.01" max="30" step="0.01"'),'Add grade',async d=>{await api('grade',d);await refreshAccess();$('#dialog').close();render();});
 if(name==='pushenable'||name==='pushdisable'||name==='pushtest')return notifications(name);
 if(name==='approve')return approveDay();
 if(name==='alerts')return alertsView();
 if(name==='guest')return guestDetail(id);
 if(name==='printid'){const slip=$('.id-slip');if(slip){slip.classList.add('print-slip');window.print();slip.classList.remove('print-slip');}return;}if(name==='copyid'){await navigator.clipboard.writeText(displayID(id));toast('Guest ID copied.');return;}
 if(name==='editrecord'){const [gid,st]=id.split('|'),r=records().find(r=>r.guest_id===gid&&r.station===st);$('#dialog').close();return stationForm(st,gid,r);}
 if(name==='selectevent'){const selected=state.events.find(e=>e.id===id);if(!selected)throw Error('This day is no longer available.');if(selected.kind!=='regular')focusedMissionID=selected.mission_id;await chooseContext({eventID:id,missionID:selected.mission_id});locationHash('home');return;}
 if(name==='eventform')return eventForm(id);
 if(name==='memberform')return memberForm(id);
 if(name==='createuser')return bulkVolunteerForm();
 if(name==='teamadd')return addMissionMembers();
 if(name==='teamremove'){if(!confirm('Remove this person’s access to this trip? Existing attendance stays saved.'))return;await api('team-assign',{mission_id:teamMission,id,user_ids:[id],active:false});await refreshAccess();render();return;}
 if(name==='teamsave')return saveAttendance();
 if(name==='teamexport')return exportAttendance();
 if(name==='appointment')return appointmentForm(id);
 if(name==='recipe')return recipeForm(id);
 if(name==='recipeview')return recipeView(id);
 if(name==='export')return exportCSV();
 if(name==='password'){authView('password');return;}
 if(name==='alertday'){$('#dialog').close();const selected=state.events.find(e=>e.id===id);if(!selected)throw Error('This day is no longer available.');await chooseContext({eventID:id,missionID:selected.mission_id});location.hash='sync';return;}
 if(name==='resolveconflict'){await api('resolve',{id});await sync();return;}
 if(name==='reviewconflict'){const c=snap().conflicts.find(c=>c.id===id),o=c.operation,r=records().find(r=>r.guest_id===o.guest_id&&r.station===o.station);if(!r)throw Error('Sync the event before reviewing.');show('Compare station submissions',`<div class="grid-two"><section><h3>Current record</h3><pre>${esc(JSON.stringify(r.data,null,2))}</pre></section><section><h3>Incoming submission</h3><pre>${esc(JSON.stringify(o.data,null,2))}</pre></section></div><p>After reviewing, open the guest record to make a correction, or keep the current version.</p>${button('conflictguest','Open current record',o.guest_id,'secondary')}`,null);return;}
 if(name==='conflictguest'){$('#dialog').close();return guestDetail(id);}
 if(name==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null;}else toast('Open your browser menu and choose Install app or Add to Home Screen.');return;}
}
