function impactBars(values,unit='registrations'){const items=Object.entries(values).sort(([a],[b])=>a.localeCompare(b)),max=Math.max(1,...items.map(([,n])=>n));return `<div class="service-chart" role="img" aria-label="${esc(items.map(([label,n])=>label+': '+n+' '+unit).join('; ')||'No data')}">${items.map(([label,n])=>`<div><span>${esc(label)}</span><i><b style="width:${100*n/max}%"></b></i><strong>${n}</strong></div>`).join('')}</div>`;}
function downloadCSV(rows,name){const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function guidePage(){return `<section class="hero"><div><div class="eyebrow">Volunteer preparation</div><h2>Ready before the first guest arrives.</h2><p>Practice here while waiting for your mission code. Practice values stay on this screen and never create guest records.</p><div class="actions">${button('joinmission','Enter mission code')}${button('prepare','Prepare / refresh phone','','secondary')}</div></div></section><div class="grid-two"><section class="panel"><h2>Before leaving</h2>${[['joined','I have joined the correct mission.'],['session','I checked the date and location.'],['phone','I prepared this phone online.'],['airplane','I tested opening the app in airplane mode.'],['power','I have charged the phone and arranged a power bank.']].map(([id,label])=>`<label class="checkline"><input type="checkbox" data-ready="${id}" ${state.readiness?.[id]?'checked':''}>${label}</label>`).join('')}<p class="subtext">Your checklist is saved on this phone. Each phone must prepare separately.</p></section><section class="panel"><h2>Practice a guest ID</h2><p class="subtext">Practice the short ID written on the paper slip:</p><div class="id-slip">A0001</div>${field('practiceID','Practice ID','','text','autocomplete="off" autocapitalize="characters"')}<p id="practiceIDResult" role="status" class="subtext">No guest will be created.</p></section><section class="panel"><h2>Practice height, weight and BMI</h2><div class="form-grid">${field('practiceHeight','Practice height (cm)','170','number','min="30" max="250" step="0.1"')}${field('practiceWeight','Practice weight (kg)','68','number','min="1" max="400" step="0.1"')}</div><p class="bmi-box">Calculated BMI: <strong id="practiceBMI">23.5</strong></p><p class="subtext">This demonstrates the calculation only. Enter real measurements in the guest’s event form.</p></section><section class="panel"><h2>Station handover</h2><ol class="guide-steps"><li>Check the event date and location.</li><li>Registration creates the ID and gives it to the guest.</li><li>Every station enters the complete ID, then records its section.</li><li>If registration is not visible, continue using the ID.</li><li>Save on the phone. When connected, open the app and sync.</li><li>Tell the administrator when your phone has no pending uploads.</li></ol><p class="subtext">A lost slip can be recovered on the registration phone, or on another phone after registration syncs. Conflicting records go to administrator review.</p></section></div>`;}
function bindGuide(){document.querySelectorAll('[data-ready]').forEach(input=>input.onchange=async()=>{try{await vault.edit(s=>{(s.readiness||={})[input.dataset.ready]=input.checked;});state=vault.state;}catch(e){toast(e.message);}});const id=$('[name=practiceID]');if(id)id.oninput=()=>{$('#practiceIDResult').textContent=normalizeID(id.value)==='A0001'?'Correct. This practice did not save a guest.':'Enter A0001: one letter and four digits.';};for(const name of ['practiceHeight','practiceWeight']){const input=$('[name='+name+']');if(input)input.oninput=()=>{const data={height:$('[name=practiceHeight]').value,weight:$('[name=practiceWeight]').value};try{validateData('measurements',data);$('#practiceBMI').textContent=bmi(data);}catch{$('#practiceBMI').textContent='Check measurements';}};}}

async function notifications(action){
 if(!admin())throw Error('Administrator access required.');if(!navigator.onLine)throw Error('Connect to set up notifications.');
 if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window))throw Error('Notifications are unavailable in this browser. On iPhone, add Wellness to the Home Screen, then open the installed app.');
 const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();
 if(action==='pushdisable'){if(sub){await api('push-unsubscribe',{endpoint:sub.endpoint});await sub.unsubscribe();}toast('Notifications disabled on this phone.');return;}
 if(action==='pushtest'){if(!sub)throw Error('Enable notifications on this phone first.');await api('push-test',{endpoint:sub.endpoint});toast('Test notification sent.');return;}
 if(Notification.permission==='denied')throw Error('Notifications are blocked. Enable them in your browser or phone settings, then try again.');
 const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications were not enabled. In-app alerts remain available.');
 const {publicKey}=await api('push-key');if(!sub){const text=publicKey.replace(/-/g,'+').replace(/_/g,'/'),key=Uint8Array.from(atob(text+'='.repeat((4-text.length%4)%4)),c=>c.charCodeAt(0));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}
 await api('push-subscribe',{subscription:sub.toJSON()});toast('Administrator notifications enabled on this phone.');
}

