function workflowButtons(){return `<div class="workflow-grid"><section class="workflow-card"><span class="step-marker">LARGE EVENT</span><h2>Care for a community</h2><p>Open the event, choose its day and location, and record at each station.</p><a class="primary" href="#events">Open large event</a></section><section class="workflow-card regular"><span class="step-marker">REGULAR VISITS</span><h2>Your everyday guests</h2><p>Start today’s visit or find a returning guest. Use only the services they need.</p>${button('regularvisit','New regular visit')}<a class="text-button" href="#guests">Find a returning guest →</a></section></div>`;}
