function guestPage(){if(focused())return ev()?dailyGuestPage():empty('Add a day and location to register guests.');return `<div class="segmented">${button('guestmode','Guest profiles','directory',guestMode==='directory'?'primary':'secondary')}${button('guestmode','Selected day’s records','day',guestMode==='day'?'primary':'secondary')}</div><div class="actions spaced">${button('regularvisit','New regular visit')}${ev()?button('station','Open selected day’s guest form','','secondary'):''}</div>${guestMode==='day'?(ev()?dailyGuestPage():empty('Open an event day to see its records.')):`<section class="panel"><div class="panel-head"><div><h2>Guest profiles & visit history</h2><p class="subtext">Returning visits link to a profile you select. People are never merged just because their names match.</p></div><span class="badge">${directoryRows().length} profiles</span></div><label class="guest-search">Find a guest profile<input id="directorySearch" placeholder="Name, local name, phone, village or profile ID" value="${esc(directorySearch)}"></label><div id="directoryList">${directoryList()}</div><p class="subtext">${state.lastSync?'Last refreshed '+esc(new Date(state.lastSync).toLocaleString()):'Only records saved on this phone are available.'} · Team access follows joined workspaces.</p></section>`}`;}
function directoryList(){return directoryRows().map(p=>`<button class="guest-row" data-action="profile" data-id="${esc(p.id)}"><span class="avatar">${esc(p.data.name?.slice(0,2).toUpperCase()||'ID')}</span><span class="guest-info"><strong>${esc(p.data.name||'Guest')}</strong><small>${esc(p.data.local||'')} · ${esc(p.data.village||'')}</small><span class="guest-code">${esc(p.id)}</span></span><span class="visit-count">${p.visits.length} visit${p.visits.length===1?'':'s'}<small>View history →</small></span></button>`).join('')||empty('No matching profiles on this phone. Sync to refresh your team’s records.');}
async function openProfile(id){
 const p=directoryRows().find(p=>p.id===id)||profileDirectory(registrationRecords()).find(p=>p.id===id);if(!p)throw Error('Profile unavailable. Sync your records first.');
 let history=state.profileHistories?.[id]||[];
 if(navigator.onLine){try{const r=await api('history',{person_id:id});await vault.edit(s=>{(s.profileHistories||={})[id]=r.records;});state=vault.state;history=r.records;}catch(e){toast('Using saved visit history. '+e.message);}}
 const pairs=new Set(p.visits.map(v=>v.event_id+'|'+v.guest_id));history=mergeRecords([...history,...Object.values(state.snapshots).flatMap(s=>s.records||[]).filter(r=>pairs.has(r.event_id+'|'+r.guest_id))],authorizedQueue().filter(r=>pairs.has(r.event_id+'|'+r.guest_id)));
 const visits=p.visits.map(v=>({...v,event:state.events.find(e=>e.id===v.event_id),records:history.filter(r=>r.event_id===v.event_id&&r.guest_id===v.guest_id)})).sort((a,b)=>(b.event?.starts||'').localeCompare(a.event?.starts||''));
 show(p.data.name||'Guest profile',`<div class="profile-banner"><span class="badge">Guest profile</span><p class="guest-code">${esc(id)}</p><p>${esc(p.data.local||'')} · ${esc(p.data.village||'')}</p></div><div class="actions spaced">${button('profileregular','New regular visit',id)}${ev()&&!ev().closed?button('profileevent','Add to selected day',id,'secondary'):''}</div><details class="profile-section" open><summary>Personal information</summary><dl class="summary-grid">${Object.entries(p.data).filter(([k,v])=>v&&!['person_id','consent'].includes(k)).map(([k,v])=>`<dt>${esc(fieldLabel(k))}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details><h3 class="spaced">Visit history · ${visits.length}</h3>${visits.map(v=>`<section class="history-card"><div class="panel-head"><div><strong>${esc(v.event?.starts||'Date unavailable')}</strong><p>${esc(v.event?.location||'')}</p><span class="badge">${v.event?.kind==='regular'?'Regular visit':'Large event'}</span></div>${button('historyvisit','Open visit',v.event_id+'|'+v.guest_id,'secondary')}</div>${v.records.filter(r=>r.station!=='registration').map(r=>`<details class="history-service"><summary>${esc(STATIONS[r.station])} · ${esc(recordStatus(r))}</summary><dl class="summary-grid">${Object.entries(r.data).filter(([k,v])=>v&&!['person_id','consent','address'].includes(k)).map(([k,v])=>`<dt>${esc(fieldLabel(k))}</dt><dd>${esc(v)}</dd>`).join('')}</dl></details>`).join('')||'<p class="subtext">Open this visit online to load its service details.</p>'}</section>`).join('')}<p class="subtext">Offline history includes only details previously saved on this phone.</p>`,null);
}
function reportDays(){return (state.dailyMetrics||[]).map(d=>{const pending=authorizedQueue().filter(o=>o.event_id===d.id&&!['conflict','reviewed'].includes(o.status));return pending.length&&state.snapshots[d.id]?{...d,metrics:summarize(mergeRecords(state.snapshots[d.id].records,pending)),localPending:true}:d;}).concat((state.regularQueue||[]).filter(e=>canSeeEvent(state.user,state.memberships,state.events.find(x=>x.id===e.id))&&!(state.dailyMetrics||[]).some(d=>d.id===e.id)).map(e=>({...e,metrics:summarize(mergeRecords(state.snapshots[e.id]?.records||[],authorizedQueue().filter(q=>q.event_id===e.id))),localPending:true})));}
function unifiedData(){if(focused()&&eventMission()?.sample)reportFilter.scope='samples';const source=reportDays().filter(d=>(!focused()||d.mission_id===focusedMissionID)&&(reportFilter.scope==='samples'?d.sample:!d.sample&&(reportFilter.scope!=='approved'||d.approval==='approved')));return aggregateDays(source,focused()?{...reportFilter,mission:focusedMissionID,kind:'all'}:reportFilter);}
