function reportPage(){const {days,total}=unifiedData();const shown=reportFilter.service?serviceMetrics.filter(([k])=>k===reportFilter.service):serviceMetrics;return `<section class="panel report-filters"><div class="segmented">${(focused()?[]:[['all','Combined'],['large','Large events'],['regular','Regular visits']]).map(([v,l])=>button('reportkind',l,v,reportFilter.kind===v?'primary':'secondary')).join('')}</div><div class="form-grid" id="unifiedFilters">${select('scope','Report status',focused()?(eventMission()?.sample?[['samples','Fictional event']]:[['live','Preliminary + approved'],['approved','Approved results only']]):[['live','Preliminary + approved'],['approved','Approved results only'],['samples','Fictional training samples']],reportFilter.scope)}${focused()?'':select('mission','Event / workspace',[['','All events and workspaces'],...state.missions.filter(m=>reportFilter.kind==='all'||(m.kind||'large')===reportFilter.kind).map(m=>[m.id,m.name])],reportFilter.mission)}${field('from','From date',reportFilter.from,'date')}${field('to','Through date',reportFilter.to,'date')}${select('location','Location',[['','All locations'],...[...new Set(reportDays().filter(d=>!focused()||d.mission_id===focusedMissionID).map(d=>d.location))].sort()],reportFilter.location)}${select('service','Service',[['','All services'],...serviceMetrics],reportFilter.service)}</div><div class="actions spaced">${button('reporttoday','Today','','secondary')}${button('reportmonth','This month','','secondary')}${button('reportreset','Clear filters','','text-button')}</div></section><section id="reportPrintable"><div class="report-title"><div><h2>${focused()?'Event':reportFilter.kind==='regular'?'Regular-visit':reportFilter.kind==='large'?'Large-event':'Combined wellness'} summary</h2><p class="subtext">${esc(state.missions.find(m=>m.id===(focusedMissionID||reportFilter.mission))?.name||'All selected workspaces')} · ${esc(reportFilter.from||'Beginning')} – ${esc(reportFilter.to||'Latest')} · ${esc(reportFilter.location||'All locations')}</p></div><div class="actions no-print">${button('reportexport','Export CSV','','secondary')}${button('printreport','Print / Save PDF','','secondary')}</div></div>${reportFilter.from&&reportFilter.to&&reportFilter.from>reportFilter.to?note('The end date must be on or after the start date.'):''}${reportFilter.scope==='samples'?note('Fictional samples — excluded from official results.'):note(`${days.filter(d=>d.approval!=='approved').length} preliminary days · ${days.filter(d=>d.approval==='approved').length} approved days. ${visibleQueue().filter(q=>!['conflict','reviewed'].includes(q.status)).length} entries on this phone await upload. Other offline phones may still hold records.`)}<div class="report-totals"><div><strong>${total.guests}</strong><span>Distinct registered guests</span></div><div><strong>${total.visits}</strong><span>Guest visits</span></div><div><strong>${total.services}</strong><span>Completed services / activities</span></div><div><strong>${days.length}</strong><span>Days / locations</span></div></div><div class="metric-grid">${shown.map(([k,l])=>metricCard(k,l,total[k])).join('')}</div><section class="panel spaced"><h3>Services delivered</h3>${serviceChart(total)}<p class="subtext">${total.both} visits received both glasses and dental care. A returning guest counts once as a person and again as a visit. Test counts require a recorded test value.</p></section><section class="panel spaced"><details><summary class="section-toggle">Visit trends by day and location</summary><div class="grid-two"><div><h3>By day</h3>${impactBars(days.reduce((acc,d)=>(acc[d.starts]=(acc[d.starts]||0)+d.metrics.visits,acc),{}),'visits')}</div><div><h3>By location</h3>${impactBars(days.reduce((acc,d)=>(acc[d.location]=(acc[d.location]||0)+d.metrics.visits,acc),{}),'visits')}</div></div></details></section><section class="panel"><h3>Results by day and location</h3><div class="table-wrap"><table><thead><tr><th>Date / location</th><th>Type / status</th><th>Visits</th><th>Glasses recipients / pairs</th><th>Dental</th><th>Assessments</th><th>Consultations</th></tr></thead><tbody>${days.sort((a,b)=>b.starts.localeCompare(a.starts)).map(d=>`<tr><td><button class="text-button" data-action="dayreport" data-id="${esc(d.id)}">${esc(d.starts)}<br>${esc(d.location)}</button></td><td>${d.kind==='regular'?'Regular':'Large event'}<br><span class="status-pill ${d.approval==='approved'?'complete':'waiting'}">${d.approval==='approved'?'Approved':'Preliminary'}</span></td><td>${d.metrics.visits}</td><td>${d.metrics.glassesPeople} / ${d.metrics.glasses}</td><td>${d.metrics.dental}</td><td>${d.metrics.assessments}</td><td>${d.metrics.consultations}</td></tr>`).join('')}</tbody></table></div>${!days.length?empty('No matching days. Adjust the filters or begin recording visits.'):''}</section><p class="report-footnote">Prepared ${esc(new Date().toLocaleString())} · ${esc(reportFilter.scope==='approved'?'Approved results':reportFilter.scope==='samples'?'Fictional samples':'Preliminary and approved results')} · Last sync ${esc(state.lastSync?new Date(state.lastSync).toLocaleString():'not yet available')}</p></section>`;}
function impactPage(){return reportPage();}
function exportUnified(){const {days}=unifiedData();const metrics=[['guests','Distinct guests within this day'],['visits','Visits'],['services','Completed services'],...serviceMetrics];downloadCSV([['Date','Location','Event / workspace','Type','Status',...metrics.map(([,l])=>l)],...days.map(d=>[d.starts,d.location,state.missions.find(m=>m.id===d.mission_id)?.name||'',d.kind||'large',d.sample?'Fictional sample':d.approval,...metrics.map(([k])=>d.metrics[k]||0)]),['FILTERED TOTAL','','','','',...metrics.map(([k])=>unifiedData().total[k]||0)]],'Wellness-service-summary.csv');}
function serviceMatches(r,key,group){const m=summarize(group);return key==='registrations'?group.some(x=>x.station==='registration'):key==='glasses'?m.glasses>0:key==='served'?m.served>0:key==='guests'?!!group.find(x=>x.station==='registration'):Number(m[key]||0)>0;}
async function reportDetail(key){const {days}=unifiedData();let source=[];if(navigator.onLine&&days.length){const r=await api('report-records',{event_ids:days.map(d=>d.id)});source=r.records;}else source=days.flatMap(d=>state.snapshots[d.id]?.records||[]);source=mergeRecords(source,authorizedQueue().filter(q=>days.some(d=>d.id===q.event_id)));const map=new Map();for(const r of source){const id=r.event_id+'|'+r.guest_id;if(!map.has(id))map.set(id,[]);map.get(id).push(r);}const groups=[...map.values()].filter(g=>serviceMatches(g[0],key,g));show(serviceMetrics.find(([k])=>k===key)?.[1]||'Matching visits',`<p class="subtext">${groups.length} matching visits. ${navigator.onLine?'Includes the selected report days.':'Offline: only visits cached on this phone are shown.'}</p>${groups.map(g=>{const r=g.find(r=>r.station==='registration'),e=state.events.find(e=>e.id===g[0].event_id);return `<button class="guest-row" data-action="historyvisit" data-id="${esc(g[0].event_id+'|'+g[0].guest_id)}"><span class="guest-info"><strong>${esc(r?.data.name||'Awaiting registration')}</strong><small>${esc(e?.starts)} · ${esc(e?.location)}</small><span class="guest-code">${esc(displayID(g[0].guest_id,g[0].event_id))}</span></span><span>Open →</span></button>`;}).join('')||empty('No matching visits.')}`,null);}
function inventoryLocations(){return (state.inventory?.locations||[]).filter(l=>{if(focused()&&l.mission_id!==focusedMissionID)return false;const sample=state.missions.find(m=>m.id===l.mission_id)?.sample||false;return stockFilter.sample==='samples'?sample:!sample;});}
function inventoryProjection(){const inv=state.inventory||{},issues=new Map((inv.issues||[]).map(r=>[r.event_id+'|'+r.guest_id,r]));for(const q of visibleQueue().filter(q=>q.station==='glasses'&&!['conflict','reviewed'].includes(q.status))){const key=q.event_id+'|'+q.guest_id;if(q.data.status==='Provided')issues.set(key,{event_id:q.event_id,guest_id:q.guest_id,location_id:stockLocation(state.events.find(e=>e.id===q.event_id)),grade:q.data.grade,quantity:Number(q.data.quantity)||0,pending:true,updated_at:q.created_at});else issues.delete(key);}return {...inv,issues:[...issues.values()]};}
function stockRows(location=''){const inv=inventoryProjection(),ids=new Set(location?[location]:inventoryLocations().map(l=>l.id));return state.grades.map(g=>{const received=(inv.balances||[]).filter(b=>ids.has(b.location_id)&&b.grade===g.grade).reduce((n,b)=>n+Number(b.received),0),issued=inv.issues.filter(r=>ids.has(r.location_id)&&r.grade===g.grade).reduce((n,r)=>n+r.quantity,0);return {...g,received,issued,remaining:received-issued};});}
function remaining(grade){const loc=stockLocation(ev());if(state.inventory?.locations?.some(l=>l.id===loc))return stockRows(loc).find(r=>r.grade===grade)?.remaining||0;return legacyRemaining(grade);}
function inventoryPage(){if(focused())stockFilter.sample=eventMission()?.sample?'samples':'real';const locations=inventoryLocations();if(stockFilter.location&&!locations.some(l=>l.id===stockFilter.location))stockFilter.location='';const rows=stockRows(stockFilter.location).filter(r=>('+'+r.grade).includes(stockFilter.search.trim())),inv=inventoryProjection(),selected=new Set(stockFilter.location?[stockFilter.location]:locations.map(l=>l.id));const movements=[...(inv.moves||[]).filter(m=>selected.has(m.from_location)||selected.has(m.to_location)),...(inv.legacy||[]).filter(m=>selected.has('day:'+m.event_id)).map(m=>({...m,kind:'Earlier receipt / adjustment',to_location:'day:'+m.event_id})),...inv.issues.filter(i=>selected.has(i.location_id)).map(i=>({...i,id:i.event_id+'|'+i.guest_id,kind:i.pending?'Dispensed · awaiting sync':'Dispensed',from_location:i.location_id,note:'Visit '+displayID(i.guest_id,i.event_id),created_at:i.updated_at}))].filter(m=>!stockFilter.search||('+'+m.grade).includes(stockFilter.search.trim())).sort((a,b)=>(b.created_at||'').localeCompare(a.created_at||'')).slice(0,500);const name=id=>(state.inventory?.locations||[]).find(l=>l.id===id)?.name||'—';return `<section class="panel"><div class="panel-head"><div><h2>Reading glasses inventory</h2><p class="subtext">${focused()?'Glasses allocated to this event’s days and locations.':'Available stock across main storage, event days and regular visits.'}</p></div><div class="actions">${admin()?button('stockform','Record stock movement')+button('gradeform','Grade / low-stock alert','','secondary'):''}</div></div><div class="form-grid spaced" id="inventoryFilters">${focused()?'':select('sample','Stock records',[['real','Real stock'],['samples','Fictional sample stock']],stockFilter.sample)}${select('location','Stock location',[['','All selected locations'],...locations.map(l=>[l.id,(l.kind==='main'?'Main · ':l.kind==='regular'?'Regular · ':'Event · ')+l.name])],stockFilter.location)}${field('search','Find grade',stockFilter.search,'search','placeholder="Example: 1.25"')}</div><div class="report-totals"><div><strong>${rows.reduce((n,r)=>n+r.remaining,0)}</strong><span>Pairs available</span></div><div><strong>${rows.reduce((n,r)=>n+r.issued,0)}</strong><span>Pairs dispensed</span></div><div><strong>${rows.filter(r=>r.remaining<=Number(r.low_stock??5)).length}</strong><span>Grades at / below alert</span></div><div><strong>${selected.size}</strong><span>Stock locations</span></div></div>${note(`Stock reflects the last sync${inv.asOf?' at '+esc(new Date(inv.asOf).toLocaleString()):''}, plus this phone’s saved dispensing. Other offline phones may still hold entries. Transfers move stock between locations; only a guest’s Provided record counts as dispensing.`)}<div class="table-wrap"><table class="stock-grade-table"><thead><tr><th>Grade</th><th>Available</th><th>Stock status</th><th class="stock-extra">Net received / allocated</th><th class="stock-extra">Dispensed</th></tr></thead><tbody>${rows.map(r=>`<tr><th>+${esc(r.grade)}<small class="stock-mobile-detail">Received ${r.received}<br>Issued ${r.issued}</small></th><td class="${r.remaining<0?'stock-negative':''}"><strong>${r.remaining}</strong></td><td><span class="status-pill ${r.remaining<0?'error':r.remaining<=Number(r.low_stock??5)?'waiting':'complete'}">${r.remaining<0?'Reconcile':r.remaining===0?'Out of stock':r.remaining<=Number(r.low_stock??5)?'Low stock':'Available'}</span></td><td class="stock-extra">${r.received}</td><td class="stock-extra">${r.issued}</td></tr>`).join('')}</tbody></table></div></section><section class="panel spaced"><div class="panel-head"><h2>Stock movements & dispensing</h2>${button('stockexport','Export stock CSV','','secondary')}</div><p class="subtext">Latest 500 matching entries. Correcting a guest’s glasses record recalculates dispensing; the correction remains in Edit history.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th>Movement</th><th>From → To</th><th>Grade / pairs</th><th>Reference</th></tr></thead><tbody>${movements.map(m=>`<tr><td>${esc(m.created_at?new Date(m.created_at).toLocaleDateString():'—')}</td><td>${esc(m.kind)}</td><td>${esc(name(m.from_location))} → ${esc(name(m.to_location))}</td><td>+${esc(m.grade)} / ${m.quantity}</td><td>${esc(m.note||'')}</td></tr>`).join('')}</tbody></table></div>${!movements.length?empty('No movements for this selection.'):''}</section>`;}
function stockForm(){if(!navigator.onLine)throw Error('Connect to record a stock movement. Guest dispensing continues to save offline.');const locations=focused()?(state.inventory?.locations||[]).filter(l=>l.id==='main'||l.mission_id===focusedMissionID):inventoryLocations(),options=locations.map(l=>[l.id,l.name]),id=crypto.randomUUID();if(!locations.length)throw Error('Create a workspace or event day first.');show('Record stock movement',`<div class="form-grid">${select('kind','Movement type',[['receipt','Receive new stock'],['transfer','Transfer to event / regular visits'],['return','Return unused stock'],['damage','Damaged / lost pairs'],['adjustment','Stock-count correction']])}${select('grade','Glasses grade',state.grades.map(g=>[g.grade,'+'+g.grade]))}<div id="stockFrom">${select('from_location','From location',options,stockFilter.location||'main')}</div><div id="stockTo">${select('to_location','To location',options,stockFilter.location||'main')}</div>${field('quantity','Quantity (pairs)','','number','required step="1"')}${area('note','Reason / delivery reference')}</div><p class="subtext">Use positive quantities. Stock-count corrections can be positive or negative. Confirm all dispensing phones have synced before transferring remaining stock.</p>`,'Save movement',async d=>{const kind=d.kind,item={...d,id,quantity:Number(d.quantity),from_location:['receipt','adjustment'].includes(kind)?null:d.from_location,to_location:kind==='damage'?null:d.to_location};await api('inventory-move',{item});$('#dialog').close();await refreshAccess();render();toast('Stock movement saved.');});const update=()=>{const kind=$('#modalForm [name=kind]').value;$('#stockFrom').hidden=['receipt','adjustment'].includes(kind);$('#stockTo').hidden=kind==='damage';const quantity=$('#modalForm [name=quantity]');if(kind==='adjustment')quantity.removeAttribute('min');else quantity.min='1';};$('#modalForm [name=kind]').onchange=update;update();}
function bindCareUI(){if($('#directorySearch'))$('#directorySearch').oninput=e=>{directorySearch=e.target.value;$('#directoryList').innerHTML=directoryList();};for(const [id,target] of [['unifiedFilters',reportFilter],['inventoryFilters',stockFilter]]){const container=$('#'+id);if(container)container.querySelectorAll('input,select').forEach(el=>{el.onchange=()=>{target[el.name]=el.value;render();};});}}
async function careAction(name,id){
 if(name==='openworkspace'){await enterEvent(id);return true;}
 if(name==='exitevent'){focusedMissionID='';await vault.edit(s=>{s.navigation={...s.navigation,workspaceID:''};});state=vault.state;locationHash('events');return true;}
 if(name==='nextstation'){$('#dialog').close();nextStationGuest(id);return true;}
 if(name==='dayrecords'){guestMode='day';locationHash('guests');return true;}
 if(name==='daystock'){stockFilter.location=stockLocation(ev());stockFilter.sample=ev()?.sample?'samples':'real';locationHash('inventory');return true;}
 if(name==='daymetric'){const previous={...reportFilter};reportFilter={scope:ev()?.sample?'samples':'live',kind:'all',mission:missionID,from:ev()?.starts,to:ev()?.starts,location:ev()?.location};try{await reportDetail(id);}finally{reportFilter=previous;}return true;}
 if(name==='viewrecords'){guestMode='day';locationHash('guests');return true;}
 if(name==='nextregistration'){$('#dialog').close();await stationForm('registration');return true;}
 if(name==='regularvisit'){await regularVisit(id);return true;}
 if(name==='findreturning'){$('#dialog').close();guestMode='directory';locationHash('guests');return true;}
 if(name==='guestmode'){guestMode=id;render();return true;}
 if(name==='profile'){await openProfile(id);return true;}
 if(name==='profileregular'||name==='profileevent'){const p=profileDirectory(registrationRecords()).find(p=>p.id===id);if(!p)throw Error('Guest profile unavailable.');$('#dialog').close();if(name==='profileregular')await regularVisit('',p);else{canWork();if(p.visits.some(v=>v.event_id===eventID)){const v=p.visits.find(v=>v.event_id===eventID);guestDetail(v.guest_id);}else await stationForm('registration','',null,false,{...p.data,person_id:p.id,consent:''});}return true;}
 if(name==='historyvisit'){const [eid,gid]=id.split('|'),e=state.events.find(e=>e.id===eid);if(!e)throw Error('Visit not available to this team.');$('#dialog').close();await chooseContext({eventID:eid,missionID:e.mission_id});if(navigator.onLine&&!state.snapshots[eid]){const snapshot=await api('snapshot',{event_id:eid});await vault.edit(s=>{s.snapshots[eid]=snapshot;});state=vault.state;}locationHash('stations');guestDetail(gid);return true;}
 if(name==='dayreport'){const e=state.events.find(e=>e.id===id);if(!e)throw Error('Day unavailable.');if(e.kind!=='regular')focusedMissionID=e.mission_id;await chooseContext({missionID:e.mission_id,eventID:id});locationHash('daily');return true;}
 if(name==='missionreport'){if(state.missions.find(m=>m.id===id)?.kind!=='regular')await enterEvent(id);reportFilter={...reportFilter,kind:'all',mission:id,scope:state.missions.find(m=>m.id===id)?.sample?'samples':'live',from:'',to:'',location:''};locationHash('reports');return true;}
 if(name==='eventfilter'){eventFilter=id;render();return true;}
 if(name==='reportkind'){reportFilter.kind=id;reportFilter.mission='';render();return true;}
 if(name==='reporttoday'||name==='reportmonth'){reportFilter.from=name==='reporttoday'?date():date().slice(0,7)+'-01';reportFilter.to=date();render();return true;}
 if(name==='reportreset'){reportFilter={scope:'live',kind:'all',mission:'',from:'',to:'',location:'',service:''};render();return true;}
 if(name==='reportdetail'){await reportDetail(id);return true;}
 if(name==='reportexport'){exportUnified();return true;}
 if(name==='printreport'){document.body.classList.add('printing-report');try{window.print();}finally{document.body.classList.remove('printing-report');}return true;}
 if(name==='stockexport'){downloadCSV([['Grade','Net received / allocated','Dispensed','Available','Low-stock threshold'],...stockRows(stockFilter.location).map(r=>['+'+r.grade,r.received,r.issued,r.remaining,r.low_stock??5])],'Wellness-glasses-stock.csv');return true;}
 if(name==='gradeform'){show('Glasses grade & alert threshold',`<div class="form-grid">${field('grade','Grade','','number','required min="0.01" max="30" step="0.01"')}${field('low_stock','Alert when pairs reach',5,'number','required min="0" max="100000" step="1"')}</div><p class="subtext">Entering an existing grade updates its alert threshold.</p>`,'Save grade',async d=>{await api('grade',d);await refreshAccess();$('#dialog').close();render();});return true;}
 return false;
}

// A large event owns the whole working surface until the team explicitly leaves it.
const focused=()=>!!focusedMissionID;
const eventPages=['home','stations','guests','events','inventory','reports','daily','sync','appointments','programs','team','audit'];
const eventNavGroups=[['Event workspace',['home','stations','guests','events','inventory','reports','sync']],['Team & activities',['team','appointments','programs','daily','audit']]];
const eventMission=()=>state?.missions.find(m=>m.id===focusedMissionID||m.id===missionID);
const authorizedQueue=()=>state?.queue.filter(q=>canSeeRecord(state.user,state.memberships,state.events,q))||[];
const visibleQueue=()=>authorizedQueue().filter(q=>!focused()||state.events.some(e=>e.id===q.event_id&&e.mission_id===focusedMissionID));
function displayID(id,eid=eventID){return paperID(id,state?.events.find(e=>e.id===eid)?.mission_id||missionID,state?.tickets||[]);}
function lookupID(id){return resolvePaperID(id,missionID,state.tickets||[]);}
async function refreshTickets(reserve=false){
 if(!missionID||!navigator.onLine)return;
 const mid=missionID,own=(state.tickets||[]).filter(r=>r.mission_id===mid&&r.device_id===state.device?.id&&!r.legacy_guest_id),last=own.sort((a,b)=>b.id-a.id)[0];
 const need=reserve||!!state.device&&ticketRemaining(state,mid)<25;
 const result=await api('ticket-context',{mission_id:mid,device_id:need?state.device?.id:null,after:need?last?.id??null:null});
 await vault.edit(s=>{s.tickets=[...(s.tickets||[]).filter(r=>r.mission_id!==mid),...result.ranges];});state=vault.state;
}
async function ensureTickets(){if(!ticketRemaining(state,missionID))await refreshTickets(true);if(!ticketRemaining(state,missionID))throw Error('Prepare this phone online inside this event before registering guests offline.');}
async function enterEvent(mid){
 const m=state.missions.find(m=>m.id===mid);if(!m)throw Error('Event unavailable. Sync and try again.');
 focusedMissionID=mid;guestMode='day';search='';reportFilter={scope:m.sample?'samples':'live',kind:'all',mission:mid,from:'',to:'',location:'',service:''};stockFilter={location:'',search:'',sample:m.sample?'samples':'real'};
 await chooseContext({missionID:mid});locationHash('home');
}
function eventHeading(){const m=eventMission();return `<section class="event-heading"><div class="event-breadcrumb">${button('exitevent','← All events','','text-button')}<span class="badge">${m?.sample?'Fictional sample':'Event workspace'}</span></div><div class="panel-head"><div><h1>${esc(m?.name||'Event')}</h1><p class="subtext">${esc([m?.province,m?.country].filter(Boolean).join(' · '))}</p></div><div class="actions">${button('sync','Sync now','','secondary')}${button('prepare','Prepare phone','','secondary')}</div></div>${eventContext()}<nav class="event-shortcuts" aria-label="Event team and activities"><a href="#team">Team & attendance</a><a href="#appointments">Appointments</a><a href="#programs">Programs & recipes</a></nav></section>`;}
function eventContext(){const days=state.events.filter(d=>d.mission_id===focusedMissionID).sort((a,b)=>a.starts.localeCompare(b.starts)||a.location.localeCompare(b.location));return `<div class="event-day-bar">${select('activeEvent','Day and location',days.length?days.map(d=>[d.id,d.starts+' · '+d.location]):[['','No days scheduled']],eventID)}<span class="badge">${ev()?.approval==='approved'?'Approved · read only':ev()?'Day in progress':'Add a day to begin'}</span></div>`;}
function eventOverview(){const m=eventMission(),q=visibleQueue().length;return `<section class="start-panel"><div><div class="eyebrow">${esc(ev()?.starts||'Event setup')}</div><h2>${ev()?'Ready for the next guest':'Set up your event'}</h2><p class="subtext">${ev()?esc(ev().location)+' · Registration and every station stay connected here.':'Add a day and location to start registering guests.'}</p></div><div class="start-actions">${ev()?button('newregistration','Register a new guest')+button('station','Enter a guest ID','','secondary'):admin()?button('eventform','Add day and location'):''}</div></section>${!state.device||!ticketRemaining(state,missionID)?`<section class="prepare-banner"><div><strong>Prepare guest numbers for this phone</strong><p class="subtext">Connect once before recording offline.</p></div>${button('prepare','Prepare this phone')}</section>`:''}${ev()?cards(summarize(records())):''}<div class="event-tool-grid">${[['stations','Stations','Registration, assessment and services'],['guests','Guests & queue','Find an ID and continue a guest’s form'],['inventory','Event glasses stock','Available pairs and event movements'],['reports','Event reports','Results across this event’s days'],['events','Days & locations','Schedule and event details'],['team','Team & attendance','Volunteer group and attendance by location'],['sync','Sync & review',q+' saved entries awaiting sync or review']].map(([p,title,caption])=>`<a class="panel event-tool" href="#${p}">${icon(p)}<strong>${title}</strong><span>${esc(caption)}</span></a>`).join('')}</div>`;}
function eventCalendar(){const m=eventMission(),days=state.events.filter(e=>e.mission_id===focusedMissionID).sort((a,b)=>a.starts.localeCompare(b.starts));return `<section class="panel"><div class="panel-head"><h2>Days & locations</h2><div class="actions">${admin()?button('eventform','Add day and location')+button('missionform','Event details / team code',m.id,'secondary'):''}</div></div><p class="subtext">${esc(m.notes||'Every day belongs to this event.')}</p><div class="calendar-days">${days.map(e=>`<article class="calendar-day ${e.id===eventID?'selected':''}"><div class="date-square">${esc(e.starts.slice(0,7))}<b>${esc(e.starts.slice(8))}</b></div><div><h3>${esc(e.location)}</h3><p>${esc(e.name)}</p><span class="badge">${e.approval==='approved'?'Approved':'Preliminary'}</span></div><div class="actions">${button('selectevent','Open day',e.id)}${button('dayreport','Daily report',e.id,'secondary')}${admin()?button('eventform','Edit day',e.id,'text-button'):''}</div></article>`).join('')||empty('No days scheduled yet.')}</div></section>`;}
